UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Каждый член больше предыдущего на $d$","blocks":[{"type":"formula","tex":"a_{n+1} = a_n + d \\qquad a_n = a_1 + (n - 1)d"},{"type":"list","items":["$d$ — разность. $d > 0$ — возрастает, $d < 0$ — убывает.","$2, 5, 8, 11, \\ldots$: $a_1 = 2$, $d = 3$, $a_{20} = 2 + 19 \\cdot 3 = 59$."]}]},{"kicker":"Сумма","title":"Сумма первых $n$ членов","blocks":[{"type":"formula","tex":"S_n = \\frac{a_1 + a_n}{2} \\cdot n = \\frac{2a_1 + (n - 1)d}{2} \\cdot n"},{"type":"list","items":["Сумма $1 + 2 + \\ldots + 100 = \\frac{1 + 100}{2} \\cdot 100 = 5050$.","Первую формулу бери, если известен последний член, вторую — если известна разность."]}]},{"kicker":"Свойства","title":"Средний член и симметрия","blocks":[{"type":"formula","tex":"a_n = \\frac{a_{n-1} + a_{n+1}}{2} \\qquad a_k + a_m = a_p + a_q,\\ \\text{если}\\ k + m = p + q"},{"type":"list","items":["$a_3 + a_9 = a_5 + a_7 = 2a_6$.","Числа $x, y, z$ образуют прогрессию, если $2y = x + z$."]}]},{"kicker":"Два члена","title":"Найти $a_1$ и $d$","blocks":[{"type":"text","text":"Если даны $a_m$ и $a_k$: $d = \\frac{a_k - a_m}{k - m}$, затем $a_1 = a_m - (m - 1)d$."},{"type":"note","text":"$a_4 = 10$, $a_9 = 25$: $d = \\frac{15}{5} = 3$, $a_1 = 10 - 9 = 1$."}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["В формуле $a_n$ множитель $(n - 1)$, а не $n$.","Число членов от $a_k$ до $a_m$ включительно: $m - k + 1$.","Сумма с 5-го по 10-й член: $S_{10} - S_4$, а не $S_{10} - S_5$.","Номер члена — натуральное число: если получилось дробное, такого члена нет."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Әр мүше алдыңғысынан $d$-ға артық","blocks":[{"type":"formula","tex":"a_{n+1} = a_n + d \\qquad a_n = a_1 + (n - 1)d"},{"type":"list","items":["$d$ — айырым. $d > 0$ — өспелі, $d < 0$ — кемімелі.","$2, 5, 8, 11, \\ldots$: $a_1 = 2$, $d = 3$, $a_{20} = 2 + 19 \\cdot 3 = 59$."]}]},{"kicker":"Қосынды","title":"Алғашқы $n$ мүшенің қосындысы","blocks":[{"type":"formula","tex":"S_n = \\frac{a_1 + a_n}{2} \\cdot n = \\frac{2a_1 + (n - 1)d}{2} \\cdot n"},{"type":"list","items":["$1 + 2 + \\ldots + 100 = \\frac{1 + 100}{2} \\cdot 100 = 5050$.","Соңғы мүше белгілі болса — бірінші формула, айырым белгілі болса — екінші."]}]},{"kicker":"Қасиеттері","title":"Ортаңғы мүше және симметрия","blocks":[{"type":"formula","tex":"a_n = \\frac{a_{n-1} + a_{n+1}}{2} \\qquad a_k + a_m = a_p + a_q,\\ k + m = p + q"},{"type":"list","items":["$a_3 + a_9 = a_5 + a_7 = 2a_6$.","$x, y, z$ сандары прогрессия құрайды, егер $2y = x + z$ болса."]}]},{"kicker":"Екі мүше","title":"$a_1$ мен $d$-ны табу","blocks":[{"type":"text","text":"$a_m$ мен $a_k$ берілсе: $d = \\frac{a_k - a_m}{k - m}$, содан кейін $a_1 = a_m - (m - 1)d$."},{"type":"note","text":"$a_4 = 10$, $a_9 = 25$: $d = \\frac{15}{5} = 3$, $a_1 = 10 - 9 = 1$."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$a_n$ формуласында $n$ емес, $(n - 1)$ көбейткіші.","$a_k$-дан $a_m$-ға дейінгі (қоса алғанда) мүшелер саны: $m - k + 1$.","5-ші мен 10-шы мүше аралығының қосындысы: $S_{10} - S_5$ емес, $S_{10} - S_4$.","Мүше нөмірі — натурал сан: бөлшек шықса, мұндай мүше жоқ."]}]}]}'::jsonb
WHERE slug = 'arithmetic-progression' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Что такое корень","blocks":[{"type":"text","text":"**Квадратный корень** из $a$ — число, квадрат которого равен $a$. **Арифметический** корень $\\sqrt{a}$ — неотрицательный из них."},{"type":"formula","tex":"\\sqrt{a} = b \\iff b \\ge 0,\\ b^2 = a"},{"type":"list","items":["$\\sqrt{a}$ существует только при $a \\ge 0$.","$\\sqrt{49} = 7$, а не $\\pm 7$. Знак $\\pm$ появляется при решении $x^2 = 49$.","Корень $n$-й степени: $\\sqrt[n]{a} = b \\iff b^n = a$. При чётном $n$ нужны $b \\ge 0$ и $a \\ge 0$, при нечётном — любое $a$: $\\sqrt[3]{-8} = -2$."]}]},{"kicker":"Главная ловушка","title":"Корень из квадрата","blocks":[{"type":"formula","tex":"\\sqrt{a^2} = |a|"},{"type":"list","items":["$\\sqrt{(-5)^2} = |-5| = 5$.","$\\sqrt{(2 - \\sqrt{5})^2} = |2 - \\sqrt{5}| = \\sqrt{5} - 2$, потому что $\\sqrt{5} > 2$.","Для нечётной степени модуль не нужен: $\\sqrt[3]{a^3} = a$."]},{"type":"note","text":"Перед тем как снять корень с квадрата, определи знак выражения под квадратом."}]},{"kicker":"Свойства","title":"Как работать с корнями","blocks":[{"type":"formula","tex":"\\sqrt{ab} = \\sqrt{a}\\sqrt{b} \\qquad \\sqrt{\\frac{a}{b}} = \\frac{\\sqrt{a}}{\\sqrt{b}} \\qquad (\\sqrt{a})^2 = a"},{"type":"list","items":["Свойства верны при $a \\ge 0$, $b \\ge 0$ (в дроби $b > 0$).","$\\sqrt{2} \\cdot \\sqrt{18} = \\sqrt{36} = 6$.","$\\frac{\\sqrt{75}}{\\sqrt{3}} = \\sqrt{25} = 5$.","Корня из суммы по частям не бывает: $\\sqrt{9 + 16} = 5$, а $\\sqrt{9} + \\sqrt{16} = 7$."]}]},{"kicker":"Приём","title":"Вынесение множителя из-под корня","blocks":[{"type":"text","text":"Разложи подкоренное число так, чтобы один множитель был точным квадратом."},{"type":"list","items":["$\\sqrt{50} = \\sqrt{25 \\cdot 2} = 5\\sqrt{2}$.","$\\sqrt{72} = \\sqrt{36 \\cdot 2} = 6\\sqrt{2}$.","Обратно — внесение: $3\\sqrt{2} = \\sqrt{9 \\cdot 2} = \\sqrt{18}$. Так удобно сравнивать корни."]},{"type":"note","text":"Сравни $2\\sqrt{7}$ и $3\\sqrt{3}$: $\\sqrt{28}$ и $\\sqrt{27}$, значит $2\\sqrt{7}$ больше."}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["$\\sqrt{a^2} = a$ — неверно при $a < 0$. Правильно: $|a|$.","$\\sqrt{a + b} \\ne \\sqrt{a} + \\sqrt{b}$.","$\\sqrt{0{,}09} = 0{,}3$, а не $0{,}03$.","Отрицательное число под корнем чётной степени — выражение не имеет смысла."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Түбір дегеніміз не","blocks":[{"type":"text","text":"$a$ санының **квадрат түбірі** — квадраты $a$-ға тең сан. **Арифметикалық** түбір $\\sqrt{a}$ — олардың теріс емесі."},{"type":"formula","tex":"\\sqrt{a} = b \\iff b \\ge 0,\\ b^2 = a"},{"type":"list","items":["$\\sqrt{a}$ тек $a \\ge 0$ болғанда бар.","$\\sqrt{49} = 7$, $\\pm 7$ емес. $\\pm$ таңбасы $x^2 = 49$ теңдеуін шешкенде пайда болады.","$n$-дәрежелі түбір: $\\sqrt[n]{a} = b \\iff b^n = a$. Жұп $n$ үшін $a \\ge 0$ және $b \\ge 0$ болуы керек, тақ $n$ үшін кез келген $a$: $\\sqrt[3]{-8} = -2$."]}]},{"kicker":"Басты қақпан","title":"Квадраттан алынған түбір","blocks":[{"type":"formula","tex":"\\sqrt{a^2} = |a|"},{"type":"list","items":["$\\sqrt{(-5)^2} = |-5| = 5$.","$\\sqrt{(2 - \\sqrt{5})^2} = |2 - \\sqrt{5}| = \\sqrt{5} - 2$, себебі $\\sqrt{5} > 2$.","Тақ дәреже үшін модуль керек емес: $\\sqrt[3]{a^3} = a$."]},{"type":"note","text":"Квадраттан түбірді алмас бұрын квадраттың ішіндегі өрнектің таңбасын анықта."}]},{"kicker":"Қасиеттері","title":"Түбірлермен қалай жұмыс істеу керек","blocks":[{"type":"formula","tex":"\\sqrt{ab} = \\sqrt{a}\\sqrt{b} \\qquad \\sqrt{\\frac{a}{b}} = \\frac{\\sqrt{a}}{\\sqrt{b}} \\qquad (\\sqrt{a})^2 = a"},{"type":"list","items":["Қасиеттер $a \\ge 0$, $b \\ge 0$ болғанда орындалады (бөлшекте $b > 0$).","$\\sqrt{2} \\cdot \\sqrt{18} = \\sqrt{36} = 6$.","$\\frac{\\sqrt{75}}{\\sqrt{3}} = \\sqrt{25} = 5$.","Қосындыдан түбір бөлек алынбайды: $\\sqrt{9 + 16} = 5$, ал $\\sqrt{9} + \\sqrt{16} = 7$."]}]},{"kicker":"Тәсіл","title":"Көбейткішті түбір астынан шығару","blocks":[{"type":"text","text":"Түбір астындағы санды бір көбейткіші толық квадрат болатындай жікте."},{"type":"list","items":["$\\sqrt{50} = \\sqrt{25 \\cdot 2} = 5\\sqrt{2}$.","$\\sqrt{72} = \\sqrt{36 \\cdot 2} = 6\\sqrt{2}$.","Кері амал — енгізу: $3\\sqrt{2} = \\sqrt{9 \\cdot 2} = \\sqrt{18}$. Түбірлерді салыстыруға ыңғайлы."]},{"type":"note","text":"$2\\sqrt{7}$ мен $3\\sqrt{3}$-ті салыстыр: $\\sqrt{28}$ және $\\sqrt{27}$, демек $2\\sqrt{7}$ үлкен."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$\\sqrt{a^2} = a$ — $a < 0$ болғанда қате. Дұрысы: $|a|$.","$\\sqrt{a + b} \\ne \\sqrt{a} + \\sqrt{b}$.","$\\sqrt{0{,}09} = 0{,}3$, $0{,}03$ емес.","Жұп дәрежелі түбір астындағы теріс сан — өрнектің мағынасы жоқ."]}]}]}'::jsonb
WHERE slug = 'arithmetic-roots' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Сложение","title":"Двоичное сложение","blocks":[{"type":"list","items":["$0 + 0 = 0$, $0 + 1 = 1$, $1 + 1 = 10$ (0 и перенос 1), $1 + 1 + 1 = 11$.","Складывай столбиком справа налево, как в десятичной.","Пример: $1011_2 + 110_2 = 10001_2$ ($11 + 6 = 17$)."]},{"type":"note","text":"Проверка: переведи слагаемые и ответ в десятичную систему."}]},{"kicker":"Вычитание","title":"Заём из старшего разряда","blocks":[{"type":"list","items":["$10_2 - 1_2 = 1_2$: занимаешь единицу старшего разряда, она равна основанию.","В восьмеричной заём равен 8, в шестнадцатеричной — 16.","Пример: $1000_2 - 1_2 = 111_2$."]}]},{"kicker":"Другие основания","title":"Перенос при достижении основания","blocks":[{"type":"list","items":["Восьмеричная: $7_8 + 1_8 = 10_8$; $5_8 + 6_8 = 13_8$ ($11 = 8 + 3$).","Шестнадцатеричная: $9_{16} + 7_{16} = 10_{16}$; $F_{16} + 1_{16} = 10_{16}$.","Если запутался — переведи в десятичную, посчитай и переведи обратно."]}]},{"kicker":"Типовая задача","title":"Найти основание","blocks":[{"type":"text","text":"«В системе с основанием $q$ число 17 записывается как $21$». Составь уравнение: $2q + 1 = 17$, $q = 8$."},{"type":"list","items":["Основание больше любой цифры записи: в записи $35_q$ основание не меньше 6.","Число оканчивается на 0 в системе $q$ — значит, делится на $q$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Пишут $1 + 1 = 2$ в двоичной.","При заёме в восьмеричной занимают 10, а не 8.","Забывают последний перенос в старший разряд.","Проверяют ответ в той же системе — лучше через десятичную."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Қосу","title":"Екілік қосу","blocks":[{"type":"list","items":["$0 + 0 = 0$, $0 + 1 = 1$, $1 + 1 = 10$ (0 және 1 көшіру), $1 + 1 + 1 = 11$.","Ондықтағыдай оңнан солға бағанмен қос.","Мысал: $1011_2 + 110_2 = 10001_2$ ($11 + 6 = 17$)."]},{"type":"note","text":"Тексеру: қосылғыштар мен жауапты ондық жүйеге аудар."}]},{"kicker":"Азайту","title":"Үлкен разрядтан алу","blocks":[{"type":"list","items":["$10_2 - 1_2 = 1_2$: үлкен разрядтан бірлік аласың, ол негізге тең.","Сегіздікте алынатын бірлік 8-ге, он алтылықта 16-ға тең.","Мысал: $1000_2 - 1_2 = 111_2$."]}]},{"kicker":"Басқа негіздер","title":"Негізге жеткенде көшіру","blocks":[{"type":"list","items":["Сегіздік: $7_8 + 1_8 = 10_8$; $5_8 + 6_8 = 13_8$ ($11 = 8 + 3$).","Он алтылық: $9_{16} + 7_{16} = 10_{16}$; $F_{16} + 1_{16} = 10_{16}$.","Шатассаң — ондыққа аударып, есептеп, кері аудар."]}]},{"kicker":"Типтік есеп","title":"Негізді табу","blocks":[{"type":"text","text":"«$q$ негізді жүйеде 17 саны $21$ болып жазылады». Теңдеу құр: $2q + 1 = 17$, $q = 8$."},{"type":"list","items":["Негіз жазбадағы кез келген цифрдан үлкен: $35_q$ жазбасында негіз 6-дан кем емес.","$q$ жүйесінде сан 0-мен аяқталса — ол $q$-ға бөлінеді."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Екілікте $1 + 1 = 2$ деп жазады.","Сегіздікте 8-дің орнына 10 алады.","Үлкен разрядқа соңғы көшіруді ұмытады.","Жауапты сол жүйеде тексереді — ондық арқылы тексерген дұрыс."]}]}]}'::jsonb
