UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Характеристики","title":"Период, частота, угловая скорость","blocks":[{"type":"formula","tex":"T = \\frac{t}{N} \\qquad \\nu = \\frac{1}{T} \\qquad \\omega = \\frac{2\\pi}{T} = 2\\pi\\nu"},{"type":"list","items":["$T$ — время одного оборота, с.","$\\nu$ — число оборотов в секунду, Гц (об/с).","$\\omega$ — угол поворота за секунду, рад/с."]}]},{"kicker":"Скорость","title":"Линейная скорость","blocks":[{"type":"formula","tex":"v = \\frac{2\\pi R}{T} = \\omega R"},{"type":"list","items":["Направлена по касательной к окружности.","Все точки вращающегося диска имеют одинаковую $\\omega$, но разную $v$: дальше от центра — быстрее.","Точки ремённой передачи и обода колёс в зацеплении имеют одинаковую $v$."]}]},{"kicker":"Ускорение","title":"Центростремительное ускорение","blocks":[{"type":"formula","tex":"a = \\frac{v^2}{R} = \\omega^2 R"},{"type":"list","items":["Направлено к центру окружности.","Модуль скорости постоянен, но направление меняется — поэтому ускорение есть.","Увеличили скорость в 2 раза — ускорение выросло в 4 раза."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Равномерное движение по окружности — движение **с ускорением**.","Об/мин переводят в Гц делением на 60.","Ускорение пропорционально квадрату скорости, а не скорости.","На одной оси одинаковы $\\omega$ и $T$; на одном ремне одинакова $v$."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Сипаттамалары","title":"Период, жиілік, бұрыштық жылдамдық","blocks":[{"type":"formula","tex":"T = \\frac{t}{N} \\qquad \\nu = \\frac{1}{T} \\qquad \\omega = \\frac{2\\pi}{T} = 2\\pi\\nu"},{"type":"list","items":["$T$ — бір айналым уақыты, с.","$\\nu$ — секундтағы айналымдар саны, Гц (айн/с).","$\\omega$ — секундтағы бұрылу бұрышы, рад/с."]}]},{"kicker":"Жылдамдық","title":"Сызықтық жылдамдық","blocks":[{"type":"formula","tex":"v = \\frac{2\\pi R}{T} = \\omega R"},{"type":"list","items":["Шеңберге жанама бойымен бағытталған.","Айналатын дискінің барлық нүктелерінде $\\omega$ бірдей, ал $v$ әртүрлі: центрден алыс — жылдамырақ.","Белдікті беріліс нүктелері мен ілініскен дөңгелектердің шеттерінде $v$ бірдей."]}]},{"kicker":"Үдеу","title":"Центрге тартқыш үдеу","blocks":[{"type":"formula","tex":"a = \\frac{v^2}{R} = \\omega^2 R"},{"type":"list","items":["Шеңбердің центріне бағытталған.","Жылдамдық модулі тұрақты, бірақ бағыты өзгереді — сондықтан үдеу бар.","Жылдамдықты 2 есе арттырса — үдеу 4 есе артады."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Шеңбер бойымен бірқалыпты қозғалыс — **үдеумен** қозғалыс.","айн/мин-ты Гц-ке 60-қа бөліп аударады.","Үдеу жылдамдыққа емес, оның квадратына пропорционал.","Бір осьте $\\omega$ мен $T$ бірдей; бір белдікте $v$ бірдей."]}]}]}'::jsonb
