UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Виды энергии","title":"Кинетическая и потенциальная","blocks":[{"type":"formula","tex":"E_k = \\frac{mv^2}{2} \\qquad E_p = mgh \\qquad E_p = \\frac{kx^2}{2}"},{"type":"list","items":["$E_k$ — энергия движения, всегда $\\ge 0$.","$E_p = mgh$ — зависит от выбора нулевого уровня.","$E_p = \\frac{kx^2}{2}$ — энергия деформированной пружины."]}]},{"kicker":"Закон сохранения","title":"Полная механическая энергия","blocks":[{"type":"formula","tex":"E_k + E_p = \\text{const}"},{"type":"list","items":["Выполняется, если нет трения и сопротивления.","Тело падает с высоты $h$: $mgh = \\frac{mv^2}{2}$, $v = \\sqrt{2gh}$ — масса сокращается.","Маятник: в нижней точке максимум $E_k$, в крайних — максимум $E_p$."]}]},{"kicker":"С трением","title":"Энергия переходит в тепло","blocks":[{"type":"formula","tex":"E_{\\text{нач}} = E_{\\text{кон}} + |A_{\\text{тр}}|"},{"type":"list","items":["Если трение — единственная сила, меняющая полную механическую энергию, её изменение равно работе трения.","Выделившееся тепло $Q = |A_{\\text{тр}}|$."]},{"type":"note","text":"Брусок 2 кг соскользнул с высоты 5 м и внизу имеет скорость 8 м/с: $|A_{\\text{тр}}| = 100 - 64 = 36$ Дж."}]},{"kicker":"Теорема","title":"Теорема о кинетической энергии","blocks":[{"type":"formula","tex":"A_{\\text{всех сил}} = E_{k2} - E_{k1}"},{"type":"list","items":["Работа равнодействующей равна изменению кинетической энергии.","Тормозной путь: $\\mu mgs = \\frac{mv^2}{2}$ → $s = \\frac{v^2}{2\\mu g}$. Скорость в 2 раза больше — путь в 4 раза больше."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Применяют закон сохранения механической энергии при неупругом ударе.","Скорость увеличили в 2 раза — $E_k$ выросла в 4 раза, а не в 2.","В верхней точке броска под углом $E_k \\ne 0$: горизонтальная скорость остаётся.","Путают высоту с длиной наклонной плоскости."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Энергия түрлері","title":"Кинетикалық және потенциалдық","blocks":[{"type":"formula","tex":"E_k = \\frac{mv^2}{2} \\qquad E_p = mgh \\qquad E_p = \\frac{kx^2}{2}"},{"type":"list","items":["$E_k$ — қозғалыс энергиясы, әрқашан $\\ge 0$.","$E_p = mgh$ — нөлдік деңгейді таңдауға тәуелді.","$E_p = \\frac{kx^2}{2}$ — деформацияланған серіппенің энергиясы."]}]},{"kicker":"Сақталу заңы","title":"Толық механикалық энергия","blocks":[{"type":"formula","tex":"E_k + E_p = \\text{const}"},{"type":"list","items":["Үйкеліс пен кедергі болмаса орындалады.","Дене $h$ биіктіктен түседі: $mgh = \\frac{mv^2}{2}$, $v = \\sqrt{2gh}$ — масса қысқарады.","Маятник: төменгі нүктеде $E_k$ максимум, шеткі нүктелерде $E_p$ максимум."]}]},{"kicker":"Үйкеліспен","title":"Энергия жылуға айналады","blocks":[{"type":"formula","tex":"E_{\\text{бас}} = E_{\\text{соң}} + |A_{\\text{үйк}}|"},{"type":"list","items":["Толық механикалық энергияны тек үйкеліс өзгертсе, энергияның өзгерісі үйкеліс жұмысына тең.","Бөлінген жылу $Q = |A_{\\text{үйк}}|$."]},{"type":"note","text":"2 кг білеуше 5 м биіктіктен сырғанап, төменде 8 м/с жылдамдыққа ие: $|A_{\\text{үйк}}| = 100 - 64 = 36$ Дж."}]},{"kicker":"Теорема","title":"Кинетикалық энергия туралы теорема","blocks":[{"type":"formula","tex":"A_{\\text{бар. күш}} = E_{k2} - E_{k1}"},{"type":"list","items":["Тең әсерлі күштің жұмысы кинетикалық энергияның өзгерісіне тең.","Тежелу жолы: $\\mu mgs = \\frac{mv^2}{2}$ → $s = \\frac{v^2}{2\\mu g}$. Жылдамдық 2 есе үлкен — жол 4 есе үлкен."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Серпімсіз соқтығысуда механикалық энергияның сақталу заңын қолданады.","Жылдамдықты 2 есе арттырса — $E_k$ 2 есе емес, 4 есе артады.","Бұрышпен лақтырудың жоғарғы нүктесінде $E_k \\ne 0$: горизонталь жылдамдық қалады.","Биіктікті көлбеу жазықтықтың ұзындығымен шатастырады."]}]}]}'::jsonb
WHERE slug = 'energy-conservation' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Зачем","title":"Разложить — значит записать произведением","blocks":[{"type":"text","text":"Произведение удобно: его легко сокращать и приравнивать к нулю. $ab = 0 \\iff a = 0$ или $b = 0$."},{"type":"list","items":["Вынести общий множитель.","Применить формулу сокращённого умножения.","Сгруппировать.","Разложить квадратный трёхчлен через корни."],"ordered":true}]},{"kicker":"Способ 1","title":"Общий множитель за скобки","blocks":[{"type":"list","items":["$6x^3 - 9x^2 = 3x^2(2x - 3)$.","$a(x - y) + b(y - x) = (x - y)(a - b)$ — сменили знак во второй скобке.","Выноси наибольший общий множитель: и число, и наименьшую степень переменной."]}]},{"kicker":"Способ 2","title":"Группировка","blocks":[{"type":"text","text":"Разбей на пары с общим множителем, затем вынеси общую скобку."},{"type":"list","items":["$ax + ay + 3x + 3y = a(x + y) + 3(x + y) = (x + y)(a + 3)$.","$x^3 - 2x^2 - 4x + 8 = x^2(x - 2) - 4(x - 2) = (x - 2)^2(x + 2)$."]}]},{"kicker":"Способ 3","title":"Квадратный трёхчлен","blocks":[{"type":"formula","tex":"ax^2 + bx + c = a(x - x_1)(x - x_2)"},{"type":"list","items":["$x_1, x_2$ — корни уравнения $ax^2 + bx + c = 0$.","$2x^2 - 7x + 3 = 2(x - 3)\\left(x - \\frac{1}{2}\\right) = (x - 3)(2x - 1)$.","Если $D < 0$, трёхчлен на множители не раскладывается."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Забывают множитель $a$: $2x^2 - 7x + 3 \\ne (x - 3)(x - 0{,}5)$.","При вынесении минуса меняются знаки **всех** слагаемых в скобке.","Сокращать можно множители, но не слагаемые: $\\frac{x + 2}{x} \\ne 2$.","Проверяй разложение обратным раскрытием скобок."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Не үшін","title":"Жіктеу — көбейтінді түрінде жазу","blocks":[{"type":"text","text":"Көбейтінді ыңғайлы: оны қысқарту және нөлге теңестіру оңай. $ab = 0 \\iff a = 0$ немесе $b = 0$."},{"type":"list","items":["Ортақ көбейткішті жақша сыртына шығару.","Қысқаша көбейту формуласын қолдану.","Топтастыру.","Квадрат үшмүшені түбірлері арқылы жіктеу."],"ordered":true}]},{"kicker":"1-тәсіл","title":"Ортақ көбейткішті жақша сыртына шығару","blocks":[{"type":"list","items":["$6x^3 - 9x^2 = 3x^2(2x - 3)$.","$a(x - y) + b(y - x) = (x - y)(a - b)$ — екінші жақшада таңбаны ауыстырдық.","Ең үлкен ортақ көбейткішті шығар: санды да, айнымалының ең кіші дәрежесін де."]}]},{"kicker":"2-тәсіл","title":"Топтастыру","blocks":[{"type":"text","text":"Ортақ көбейткіші бар жұптарға бөл, содан кейін ортақ жақшаны шығар."},{"type":"list","items":["$ax + ay + 3x + 3y = a(x + y) + 3(x + y) = (x + y)(a + 3)$.","$x^3 - 2x^2 - 4x + 8 = x^2(x - 2) - 4(x - 2) = (x - 2)^2(x + 2)$."]}]},{"kicker":"3-тәсіл","title":"Квадрат үшмүше","blocks":[{"type":"formula","tex":"ax^2 + bx + c = a(x - x_1)(x - x_2)"},{"type":"list","items":["$x_1, x_2$ — $ax^2 + bx + c = 0$ теңдеуінің түбірлері.","$2x^2 - 7x + 3 = 2(x - 3)\\left(x - \\frac{1}{2}\\right) = (x - 3)(2x - 1)$.","$D < 0$ болса, үшмүше көбейткіштерге жіктелмейді."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$a$ көбейткішін ұмытады: $2x^2 - 7x + 3 \\ne (x - 3)(x - 0{,}5)$.","Минусты шығарғанда жақшадағы **барлық** қосылғыштардың таңбасы өзгереді.","Көбейткіштерді қысқартуға болады, қосылғыштарды — жоқ: $\\frac{x + 2}{x} \\ne 2$.","Жіктеуді жақшаны кері ашу арқылы тексер."]}]}]}'::jsonb
WHERE slug = 'factoring' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Сила тяжести и вес","title":"Это разные силы","blocks":[{"type":"formula","tex":"F_{\\text{т}} = mg \\qquad P = m(g \\pm a)"},{"type":"list","items":["**Сила тяжести** приложена к телу, действует со стороны Земли.","**Вес** приложен к опоре или подвесу.","Лифт вверх с ускорением — вес больше $mg$; вниз — меньше.","Свободное падение — **невесомость**: $P = 0$."]}]},{"kicker":"Сила упругости","title":"Закон Гука","blocks":[{"type":"formula","tex":"F_{\\text{упр}} = k|\\Delta x|"},{"type":"list","items":["$k$ — жёсткость, Н/м. Закон верен для малых деформаций.","Последовательно две пружины: $\\frac{1}{k} = \\frac{1}{k_1} + \\frac{1}{k_2}$.","Параллельно: $k = k_1 + k_2$.","Разрезали пружину пополам — жёсткость половинки в 2 раза больше."]}]},{"kicker":"Сила трения","title":"Скольжения и покоя","blocks":[{"type":"formula","tex":"F_{\\text{тр}} = \\mu N"},{"type":"list","items":["$\\mu$ — коэффициент трения, без единиц.","На горизонтальной поверхности $N = mg$; на наклонной $N = mg\\cos\\alpha$.","Трение покоя меняется от 0 до $\\mu N$ — равно приложенной силе, пока тело не сдвинулось.","Не зависит от площади соприкосновения."]}]},{"kicker":"Наклонная плоскость","title":"Разложение силы тяжести","blocks":[{"type":"list","items":["Вдоль склона: $mg\\sin\\alpha$.","Перпендикулярно склону: $mg\\cos\\alpha$.","Тело соскальзывает без трения: $a = g\\sin\\alpha$.","С трением: $a = g(\\sin\\alpha - \\mu\\cos\\alpha)$. Покоится, если $\\mu \\ge \\tan\\alpha$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Вес и сила тяжести равны только в покое или при равномерном движении.","На наклонной плоскости $N \\ne mg$.","Сила трения покоя не всегда равна $\\mu N$.","Вес измеряется в ньютонах, а не в килограммах."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Ауырлық күші және салмақ","title":"Бұлар әртүрлі күштер","blocks":[{"type":"formula","tex":"F_{\\text{ауыр}} = mg \\qquad P = m(g \\pm a)"},{"type":"list","items":["**Ауырлық күші** денеге түсірілген, Жер тарапынан әсер етеді.","**Салмақ** тірекке немесе ілгішке түсірілген.","Лифт жоғары үдеумен — салмақ $mg$-дан үлкен; төмен — кіші.","Еркін түсу — **салмақсыздық**: $P = 0$."]}]},{"kicker":"Серпімділік күші","title":"Гук заңы","blocks":[{"type":"formula","tex":"F_{\\text{серп}} = k|\\Delta x|"},{"type":"list","items":["$k$ — қатаңдық, Н/м. Заң шағын деформациялар үшін орындалады.","Екі серіппе тізбектей: $\\frac{1}{k} = \\frac{1}{k_1} + \\frac{1}{k_2}$.","Параллель: $k = k_1 + k_2$.","Серіппені екіге қиса — жартысының қатаңдығы 2 есе артады."]}]},{"kicker":"Үйкеліс күші","title":"Сырғанау және тыныштық үйкелісі","blocks":[{"type":"formula","tex":"F_{\\text{үйк}} = \\mu N"},{"type":"list","items":["$\\mu$ — үйкеліс коэффициенті, бірліксіз.","Горизонталь бетте $N = mg$; көлбеу бетте $N = mg\\cos\\alpha$.","Тыныштық үйкелісі 0-ден $\\mu N$-ге дейін өзгереді — дене қозғалғанға дейін түсірілген күшке тең.","Жанасу ауданына тәуелсіз."]}]},{"kicker":"Көлбеу жазықтық","title":"Ауырлық күшін жіктеу","blocks":[{"type":"list","items":["Көлбеу бойымен: $mg\\sin\\alpha$.","Көлбеуге перпендикуляр: $mg\\cos\\alpha$.","Үйкеліссіз сырғанайды: $a = g\\sin\\alpha$.","Үйкеліспен: $a = g(\\sin\\alpha - \\mu\\cos\\alpha)$. $\\mu \\ge \\tan\\alpha$ болса — тыныштықта."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Салмақ пен ауырлық күші тек тыныштықта не бірқалыпты қозғалыста тең.","Көлбеу жазықтықта $N \\ne mg$.","Тыныштық үйкеліс күші әрқашан $\\mu N$-ге тең емес.","Салмақ килограммен емес, ньютонмен өлшенеді."]}]}]}'::jsonb
WHERE slug = 'forces-in-mechanics' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Обыкновенные дроби","title":"Сложение и вычитание","blocks":[{"type":"text","text":"Дроби складывают только с **общим знаменателем**. Лучше брать наименьший общий кратный (НОК)."},{"type":"formula","tex":"\\frac{a}{b} + \\frac{c}{d} = \\frac{ad + cb}{bd}"},{"type":"list","items":["$\\frac{1}{4} + \\frac{1}{6} = \\frac{3}{12} + \\frac{2}{12} = \\frac{5}{12}$ (НОК(4, 6) = 12).","Смешанное число переводи в неправильную дробь: $2\\frac{1}{3} = \\frac{7}{3}$.","В ответе сокращай дробь до конца."]}]},{"kicker":"Обыкновенные дроби","title":"Умножение и деление","blocks":[{"type":"formula","tex":"\\frac{a}{b} \\cdot \\frac{c}{d} = \\frac{ac}{bd} \\qquad \\frac{a}{b} : \\frac{c}{d} = \\frac{a}{b} \\cdot \\frac{d}{c}"},{"type":"list","items":["Сокращай **до** умножения: $\\frac{6}{35} \\cdot \\frac{14}{9} = \\frac{2 \\cdot 2}{5 \\cdot 3} = \\frac{4}{15}$.","Чтобы разделить на дробь, умножь на обратную. Знаменатели и делитель должны быть ненулевыми.","Многоэтажная дробь: $\\frac{a/b}{c/d} = \\frac{ad}{bc}$."]}]},{"kicker":"Десятичные дроби","title":"Перевод и вычисления","blocks":[{"type":"list","items":["$0{,}25 = \\frac{1}{4}$, $0{,}5 = \\frac{1}{2}$, $0{,}2 = \\frac{1}{5}$, $0{,}125 = \\frac{1}{8}$, $0{,}75 = \\frac{3}{4}$ — помни наизусть.","При умножении десятичных дробей запятую ставят, отсчитав справа столько знаков, сколько их у множителей вместе: $0{,}3 \\cdot 0{,}02 = 0{,}006$.","При делении на десятичную дробь переноси запятую в обоих числах: $1{,}2 : 0{,}04 = 120 : 4 = 30$."]},{"type":"note","text":"Если в примере есть и обыкновенные, и десятичные дроби, обычно удобнее перейти к обыкновенным."}]},{"kicker":"Порядок действий","title":"Числовые выражения","blocks":[{"type":"list","items":["Действия в скобках.","Степени и корни.","Умножение и деление — слева направо.","Сложение и вычитание — слева направо."],"ordered":true},{"type":"note","text":"Пример: $2 - 3 \\cdot \\left(\\frac{1}{2}\\right)^2 = 2 - \\frac{3}{4} = 1\\frac{1}{4}$."}]},{"kicker":"Проценты","title":"Процент — это сотая часть","blocks":[{"type":"list","items":["$p\\%$ от числа $a$: $a \\cdot \\frac{p}{100}$.","Число по его части: если $p\\%$ числа равны $b$, то число $= \\frac{100b}{p}$.","Увеличить на $p\\%$ — умножить на $1 + \\frac{p}{100}$; уменьшить — на $1 - \\frac{p}{100}$."]},{"type":"trap","items":["Рост на 20% и падение на 20% не возвращают к исходному: $1{,}2 \\cdot 0{,}8 = 0{,}96$.","Складывают числители со знаменателями: $\\frac{1}{2} + \\frac{1}{3} \\ne \\frac{2}{5}$.","Делят «перевернув» не ту дробь: переворачивают делитель, а не делимое."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Жай бөлшектер","title":"Қосу және азайту","blocks":[{"type":"text","text":"Бөлшектер тек **ортақ бөлімде** қосылады. Ең кіші ортақ еселікті (ЕКОЕ) алған дұрыс."},{"type":"formula","tex":"\\frac{a}{b} + \\frac{c}{d} = \\frac{ad + cb}{bd}"},{"type":"list","items":["$\\frac{1}{4} + \\frac{1}{6} = \\frac{3}{12} + \\frac{2}{12} = \\frac{5}{12}$ (ЕКОЕ(4, 6) = 12).","Аралас санды бұрыс бөлшекке айналдыр: $2\\frac{1}{3} = \\frac{7}{3}$.","Жауапта бөлшекті соңына дейін қысқарт."]}]},{"kicker":"Жай бөлшектер","title":"Көбейту және бөлу","blocks":[{"type":"formula","tex":"\\frac{a}{b} \\cdot \\frac{c}{d} = \\frac{ac}{bd} \\qquad \\frac{a}{b} : \\frac{c}{d} = \\frac{a}{b} \\cdot \\frac{d}{c}"},{"type":"list","items":["Көбейтуден **бұрын** қысқарт: $\\frac{6}{35} \\cdot \\frac{14}{9} = \\frac{2 \\cdot 2}{5 \\cdot 3} = \\frac{4}{15}$.","Бөлшекке бөлу үшін оның кері бөлшегіне көбейт. Бөлімдер де, бөлгіш те нөлге тең болмауы керек.","Көпқабатты бөлшек: $\\frac{a/b}{c/d} = \\frac{ad}{bc}$."]}]},{"kicker":"Ондық бөлшектер","title":"Аудару және есептеу","blocks":[{"type":"list","items":["$0{,}25 = \\frac{1}{4}$, $0{,}5 = \\frac{1}{2}$, $0{,}2 = \\frac{1}{5}$, $0{,}125 = \\frac{1}{8}$, $0{,}75 = \\frac{3}{4}$ — жатқа біл.","Ондық бөлшектерді көбейткенде үтірді оң жақтан көбейткіштердегі таңбалар санының қосындысындай санап қоямыз: $0{,}3 \\cdot 0{,}02 = 0{,}006$.","Ондық бөлшекке бөлгенде екі санда да үтірді жылжыт: $1{,}2 : 0{,}04 = 120 : 4 = 30$."]},{"type":"note","text":"Мысалда жай және ондық бөлшектер аралас болса, әдетте жай бөлшекке көшкен ыңғайлы."}]},{"kicker":"Амалдар реті","title":"Сандық өрнектер","blocks":[{"type":"list","items":["Жақша ішіндегі амалдар.","Дәрежелер мен түбірлер.","Көбейту мен бөлу — солдан оңға.","Қосу мен азайту — солдан оңға."],"ordered":true},{"type":"note","text":"Мысал: $2 - 3 \\cdot \\left(\\frac{1}{2}\\right)^2 = 2 - \\frac{3}{4} = 1\\frac{1}{4}$."}]},{"kicker":"Пайыздар","title":"Пайыз — жүзден бір бөлік","blocks":[{"type":"list","items":["$a$ санының $p\\%$-ы: $a \\cdot \\frac{p}{100}$.","Бөлігі бойынша санды табу: санның $p\\%$-ы $b$-ға тең болса, сан $= \\frac{100b}{p}$.","$p\\%$-ға арттыру — $1 + \\frac{p}{100}$-ге көбейту; кеміту — $1 - \\frac{p}{100}$-ге."]},{"type":"trap","items":["20%-ға өсіп, 20%-ға кему бастапқыға қайтармайды: $1{,}2 \\cdot 0{,}8 = 0{,}96$.","Алымдарды алыммен, бөлімдерді бөліммен қосады: $\\frac{1}{2} + \\frac{1}{3} \\ne \\frac{2}{5}$.","Бөлгенде басқа бөлшекті аударады: бөлінгішті емес, бөлгішті аудару керек."]}]}]}'::jsonb
WHERE slug = 'fractions-and-numeric' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Свободное падение","title":"Движение только под действием тяжести","blocks":[{"type":"formula","tex":"v = gt \\qquad h = \\frac{gt^2}{2} \\qquad v^2 = 2gh"},{"type":"list","items":["$g \\approx 10$ м/с² (в задачах ЕНТ обычно так).","Ускорение не зависит от массы: молоток и перо в вакууме падают одинаково.","За каждую следующую секунду тело проходит пути в отношении $1 : 3 : 5 : 7 \\ldots$"]}]},{"kicker":"Бросок вверх","title":"Подъём и спуск симметричны","blocks":[{"type":"formula","tex":"t_{\\text{под}} = \\frac{v_0}{g} \\qquad h_{\\max} = \\frac{v_0^2}{2g}"},{"type":"list","items":["В верхней точке $v = 0$, но ускорение по-прежнему $g$ вниз.","Время полёта $2t_{\\text{под}}$. На ту же высоту тело возвращается с той же скоростью."]}]},{"kicker":"Горизонтальный бросок","title":"Два независимых движения","blocks":[{"type":"formula","tex":"x = v_0 t \\qquad y = h - \\frac{gt^2}{2} \\qquad t = \\sqrt{\\frac{2h}{g}}"},{"type":"list","items":["По горизонтали — равномерно, по вертикали — свободное падение.","Время полёта зависит только от высоты, не от $v_0$.","Дальность $L = v_0\\sqrt{\\frac{2h}{g}}$."]}]},{"kicker":"Бросок под углом","title":"Разложи скорость","blocks":[{"type":"formula","tex":"v_x = v_0 \\cos\\alpha \\qquad v_y = v_0 \\sin\\alpha"},{"type":"formula","tex":"t = \\frac{2v_0 \\sin\\alpha}{g} \\qquad L = \\frac{v_0^2 \\sin 2\\alpha}{g} \\qquad H = \\frac{v_0^2 \\sin^2\\alpha}{2g}"},{"type":"note","text":"Наибольшая дальность — при $\\alpha = 45°$. Углы $30°$ и $60°$ дают одинаковую дальность."}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["В верхней точке считают $a = 0$ — ускорение всегда $g$.","При горизонтальном броске подставляют $v_0$ во время падения.","Синус и косинус в разложении скорости: $v_x$ — через $\\cos$, если угол от горизонта.","Путь за $n$-ю секунду $\\ne$ путь за $n$ секунд."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Еркін түсу","title":"Тек ауырлық күшінің әсерімен қозғалыс","blocks":[{"type":"formula","tex":"v = gt \\qquad h = \\frac{gt^2}{2} \\qquad v^2 = 2gh"},{"type":"list","items":["$g \\approx 10$ м/с² (ҰБТ есептерінде әдетте осылай).","Үдеу массаға тәуелсіз: вакуумда балға мен қауырсын бірдей түседі.","Әрбір келесі секундта дене $1 : 3 : 5 : 7 \\ldots$ қатынасындағы жолдар жүреді."]}]},{"kicker":"Жоғары лақтыру","title":"Көтерілу мен түсу симметриялы","blocks":[{"type":"formula","tex":"t_{\\text{көт}} = \\frac{v_0}{g} \\qquad h_{\\max} = \\frac{v_0^2}{2g}"},{"type":"list","items":["Жоғарғы нүктеде $v = 0$, бірақ үдеу бұрынғыдай төмен қарай $g$.","Ұшу уақыты $2t_{\\text{көт}}$. Сол биіктікке дене сол жылдамдықпен оралады."]}]},{"kicker":"Горизонталь лақтыру","title":"Екі тәуелсіз қозғалыс","blocks":[{"type":"formula","tex":"x = v_0 t \\qquad y = h - \\frac{gt^2}{2} \\qquad t = \\sqrt{\\frac{2h}{g}}"},{"type":"list","items":["Горизонталь бойымен — бірқалыпты, вертикаль бойымен — еркін түсу.","Ұшу уақыты $v_0$-ге емес, тек биіктікке тәуелді.","Ұшу қашықтығы $L = v_0\\sqrt{\\frac{2h}{g}}$."]}]},{"kicker":"Бұрышпен лақтыру","title":"Жылдамдықты жікте","blocks":[{"type":"formula","tex":"v_x = v_0 \\cos\\alpha \\qquad v_y = v_0 \\sin\\alpha"},{"type":"formula","tex":"t = \\frac{2v_0 \\sin\\alpha}{g} \\qquad L = \\frac{v_0^2 \\sin 2\\alpha}{g} \\qquad H = \\frac{v_0^2 \\sin^2\\alpha}{2g}"},{"type":"note","text":"Ең үлкен қашықтық — $\\alpha = 45°$ болғанда. $30°$ пен $60°$ бұрыштары бірдей қашықтық береді."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Жоғарғы нүктеде $a = 0$ деп есептейді — үдеу әрқашан $g$.","Горизонталь лақтыруда түсу уақытына $v_0$-ді қояды.","Жылдамдықты жіктегенде синус пен косинус: бұрыш горизонттан өлшенсе, $v_x$ — $\\cos$ арқылы.","$n$-ші секундтағы жол $\\ne$ $n$ секундтағы жол."]}]}]}'::jsonb
WHERE slug = 'free-fall-projectile' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Каждый член больше предыдущего в $q$ раз","blocks":[{"type":"formula","tex":"b_{n+1} = b_n q \\qquad b_n = b_1 q^{n-1}"},{"type":"list","items":["$q$ — знаменатель, $b_1 \\ne 0$, $q \\ne 0$.","$3, 6, 12, 24, \\ldots$: $q = 2$, $b_6 = 3 \\cdot 2^5 = 96$.","$q < 0$ — знаки членов чередуются."]}]},{"kicker":"Сумма","title":"Сумма первых $n$ членов","blocks":[{"type":"formula","tex":"S_n = \\frac{b_1(q^n - 1)}{q - 1},\\quad q \\ne 1"},{"type":"list","items":["$1 + 2 + 4 + \\ldots + 2^9 = \\frac{2^{10} - 1}{1} = 1023$.","При $q = 1$ все члены равны: $S_n = nb_1$."]}]},{"kicker":"Бесконечно убывающая","title":"Когда $|q| < 1$","blocks":[{"type":"formula","tex":"S = \\frac{b_1}{1 - q}"},{"type":"list","items":["$1 + \\frac{1}{2} + \\frac{1}{4} + \\ldots = \\frac{1}{1 - 1/2} = 2$.","Периодическая дробь: $0{,}(3) = \\frac{0{,}3}{1 - 0{,}1} = \\frac{1}{3}$."]}]},{"kicker":"Свойства","title":"Среднее геометрическое","blocks":[{"type":"formula","tex":"b_n^2 = b_{n-1} b_{n+1} \\qquad b_k b_m = b_p b_q,\\ \\text{если}\\ k + m = p + q"},{"type":"list","items":["Если $x, y, z$ — геометрическая прогрессия, то $y^2 = xz$.","Два члена: $\\frac{b_k}{b_m} = q^{k-m}$. $b_2 = 6$, $b_5 = 48$ → $q^3 = 8$, $q = 2$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Степень $q^{n-1}$, а не $q^n$.","$q^2 = 4$ даёт $q = \\pm 2$ — проверяй оба знака.","Формула суммы бесконечной прогрессии — только при $|q| < 1$.","Путают с арифметической: в геометрической члены умножают, а не складывают."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Әр мүше алдыңғысынан $q$ есе артық","blocks":[{"type":"formula","tex":"b_{n+1} = b_n q \\qquad b_n = b_1 q^{n-1}"},{"type":"list","items":["$q$ — еселік, $b_1 \\ne 0$, $q \\ne 0$.","$3, 6, 12, 24, \\ldots$: $q = 2$, $b_6 = 3 \\cdot 2^5 = 96$.","$q < 0$ — мүшелердің таңбалары кезектеседі."]}]},{"kicker":"Қосынды","title":"Алғашқы $n$ мүшенің қосындысы","blocks":[{"type":"formula","tex":"S_n = \\frac{b_1(q^n - 1)}{q - 1},\\quad q \\ne 1"},{"type":"list","items":["$1 + 2 + 4 + \\ldots + 2^9 = \\frac{2^{10} - 1}{1} = 1023$.","$q = 1$ болса, барлық мүшелер тең: $S_n = nb_1$."]}]},{"kicker":"Шексіз кемімелі","title":"$|q| < 1$ болғанда","blocks":[{"type":"formula","tex":"S = \\frac{b_1}{1 - q}"},{"type":"list","items":["$1 + \\frac{1}{2} + \\frac{1}{4} + \\ldots = \\frac{1}{1 - 1/2} = 2$.","Периодты бөлшек: $0{,}(3) = \\frac{0{,}3}{1 - 0{,}1} = \\frac{1}{3}$."]}]},{"kicker":"Қасиеттері","title":"Орта геометриялық","blocks":[{"type":"formula","tex":"b_n^2 = b_{n-1} b_{n+1} \\qquad b_k b_m = b_p b_q,\\ k + m = p + q"},{"type":"list","items":["$x, y, z$ — геометриялық прогрессия болса, $y^2 = xz$.","Екі мүше: $\\frac{b_k}{b_m} = q^{k-m}$. $b_2 = 6$, $b_5 = 48$ → $q^3 = 8$, $q = 2$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Дәреже $q^n$ емес, $q^{n-1}$.","$q^2 = 4$ болса $q = \\pm 2$ — екі таңбаны да тексер.","Шексіз прогрессия қосындысының формуласы — тек $|q| < 1$ болғанда.","Арифметикалықпен шатастырады: геометриялықта мүшелер қосылмайды, көбейтіледі."]}]}]}'::jsonb
WHERE slug = 'geometric-progression' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Закон","title":"Закон всемирного тяготения","blocks":[{"type":"formula","tex":"F = G\\frac{m_1 m_2}{r^2} \\qquad G = 6{,}67 \\cdot 10^{-11}\\ \\text{Н} \\cdot \\text{м}^2/\\text{кг}^2"},{"type":"list","items":["$r$ — расстояние между **центрами** тел.","Расстояние увеличили в 2 раза — сила уменьшилась в 4 раза.","Силы взаимодействия двух тел равны по модулю (третий закон Ньютона)."]}]},{"kicker":"Ускорение свободного падения","title":"На поверхности и на высоте","blocks":[{"type":"formula","tex":"g = G\\frac{M}{R^2} \\qquad g_h = G\\frac{M}{(R + h)^2}"},{"type":"list","items":["На высоте $h = R$ ускорение в 4 раза меньше, чем у поверхности.","На другой планете: $\\frac{g_1}{g_2} = \\frac{M_1}{M_2} \\cdot \\frac{R_2^2}{R_1^2}$."]}]},{"kicker":"Спутники","title":"Первая космическая скорость","blocks":[{"type":"formula","tex":"v_1 = \\sqrt{gR} = \\sqrt{G\\frac{M}{R}} \\approx 7{,}9\\ \\text{км/с}"},{"type":"list","items":["Сила тяготения сообщает спутнику центростремительное ускорение: $\\frac{mv^2}{r} = G\\frac{Mm}{r^2}$.","Скорость на орбите радиуса $r$: $v = \\sqrt{\\frac{GM}{r}}$ — чем выше, тем медленнее.","Вторая космическая (покинуть Землю): $11{,}2$ км/с."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Берут расстояние от поверхности вместо расстояния от центра: $r = R + h$.","Сила обратно пропорциональна **квадрату** расстояния.","Масса спутника на его орбитальную скорость не влияет.","Невесомость на МКС — не отсутствие тяготения, а свободное падение."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Заң","title":"Бүкіләлемдік тартылыс заңы","blocks":[{"type":"formula","tex":"F = G\\frac{m_1 m_2}{r^2} \\qquad G = 6{,}67 \\cdot 10^{-11}\\ \\text{Н} \\cdot \\text{м}^2/\\text{кг}^2"},{"type":"list","items":["$r$ — денелердің **центрлері** арасындағы қашықтық.","Қашықтықты 2 есе арттырса — күш 4 есе кемиді.","Екі дененің өзара әсер күштері модулі бойынша тең (Ньютонның үшінші заңы)."]}]},{"kicker":"Еркін түсу үдеуі","title":"Бетінде және биіктікте","blocks":[{"type":"formula","tex":"g = G\\frac{M}{R^2} \\qquad g_h = G\\frac{M}{(R + h)^2}"},{"type":"list","items":["$h = R$ биіктікте үдеу бетіндегіден 4 есе кіші.","Басқа планетада: $\\frac{g_1}{g_2} = \\frac{M_1}{M_2} \\cdot \\frac{R_2^2}{R_1^2}$."]}]},{"kicker":"Жер серіктері","title":"Бірінші ғарыштық жылдамдық","blocks":[{"type":"formula","tex":"v_1 = \\sqrt{gR} = \\sqrt{G\\frac{M}{R}} \\approx 7{,}9\\ \\text{км/с}"},{"type":"list","items":["Тартылыс күші серікке центрге тартқыш үдеу береді: $\\frac{mv^2}{r} = G\\frac{Mm}{r^2}$.","$r$ радиусты орбитадағы жылдамдық: $v = \\sqrt{\\frac{GM}{r}}$ — неғұрлым биік болса, соғұрлым баяу.","Екінші ғарыштық (Жерден кету): $11{,}2$ км/с."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Центрден емес, беттен қашықтықты алады: $r = R + h$.","Күш қашықтықтың **квадратына** кері пропорционал.","Серіктің массасы оның орбиталық жылдамдығына әсер етпейді.","ХҒС-тағы салмақсыздық — тартылыстың жоқтығы емес, еркін түсу."]}]}]}'::jsonb
WHERE slug = 'gravitation' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Единицы","title":"Бит, байт и кратные","blocks":[{"type":"list","items":["**Бит** — наименьшая единица: 0 или 1.","$1$ байт $= 8$ бит.","$1$ КиБ $= 1024$ байт; $1$ МиБ $= 1024$ КиБ; $1$ ГиБ $= 1024$ МиБ.","Смотри условие задачи: 1 кБ = 1000 байт, а для перевода по 1024 нужна двоичная единица или явное условие."]}]},{"kicker":"Кодирование","title":"Сколько бит на один символ","blocks":[{"type":"formula","tex":"2^i \\ge N"},{"type":"list","items":["$N$ — мощность алфавита (число возможных значений), $i$ — бит на символ.","Нужно наименьшее целое $i$, при котором хватает кодов. Для 32 символов это 5 бит.","Если $N$ не степень двойки, берут ближайшую большую: 50 символов → 6 бит ($2^6 = 64$)."]}]},{"kicker":"Объём сообщения","title":"Сколько бит в тексте","blocks":[{"type":"formula","tex":"I = K \\cdot i"},{"type":"list","items":["$K$ — число символов, $i$ — бит на символ.","100 символов по 8 бит: $I = 800$ бит $= 100$ байт.","Перевод вверх — деление: биты → байты на 8, байты → КиБ на 1024."]}]},{"kicker":"Вероятностный подход","title":"Количество информации в сообщении","blocks":[{"type":"list","items":["Сообщение о том, что произошло одно из $N$ равновероятных событий, несёт $i = \\log_2 N$ бит.","«Выпал орёл»: 1 бит. «Угадано число от 1 до 64»: 6 бит.","Чем менее вероятно событие, тем больше информации в сообщении о нём."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Путают кБ (1000 байт) и КиБ (1024 байта).","Путают бит и байт: «8 КиБ» = $2^{16}$ бит.","Для 50 символов берут $\\log_2 50 \\approx 5{,}6$ и округляют вниз: для кода фиксированной длины нужно округлять вверх.","Пробелы и знаки препинания — тоже символы."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Бірліктер","title":"Бит, байт және еселіктері","blocks":[{"type":"list","items":["**Бит** — ең кіші бірлік: 0 немесе 1.","$1$ байт $= 8$ бит.","$1$ КиБ $= 1024$ байт; $1$ МиБ $= 1024$ КиБ; $1$ ГиБ $= 1024$ МиБ.","Есептің шартын қара: 1 кБ = 1000 байт; 1024-ке ауыстыру үшін екілік бірлік немесе есепте берілген шарт қажет."]}]},{"kicker":"Кодтау","title":"Бір символға неше бит","blocks":[{"type":"formula","tex":"2^i \\ge N"},{"type":"list","items":["$N$ — алфавит қуаты (мүмкін мәндер саны), $i$ — бір символдағы бит.","Кодтар жеткілікті болатын ең кіші бүтін $i$ алынады. 32 символға 5 бит керек.","$N$ екінің дәрежесі болмаса, ең жақын үлкенін аламыз: 50 символ → 6 бит ($2^6 = 64$)."]}]},{"kicker":"Хабар көлемі","title":"Мәтінде неше бит","blocks":[{"type":"formula","tex":"I = K \\cdot i"},{"type":"list","items":["$K$ — символдар саны, $i$ — бір символдағы бит.","Әрқайсысы 8 биттен 100 символ: $I = 800$ бит $= 100$ байт.","Үлкен бірлікке көшу — бөлу: бит → байт 8-ге, байт → КиБ 1024-ке."]}]},{"kicker":"Ықтималдық тәсіл","title":"Хабардағы ақпарат мөлшері","blocks":[{"type":"list","items":["$N$ тең ықтималды оқиғаның бірі болғаны туралы хабар $i = \\log_2 N$ бит ақпарат береді.","«Елтаңба түсті»: 1 бит. «1-ден 64-ке дейінгі сан табылды»: 6 бит.","Оқиғаның ықтималдығы неғұрлым аз болса, ол туралы хабарда ақпарат соғұрлым көп."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["кБ (1000 байт) пен КиБ-ты (1024 байт) шатастырады.","Бит пен байтты шатастырады: «8 КиБ» = $2^{16}$ бит.","50 символ үшін $\\log_2 50 \\approx 5{,}6$ алады деп төмен дөңгелектейді: тұрақты ұзындықтағы код үшін жоғары дөңгелектеу керек.","Бос орындар мен тыныс белгілері — да символдар."]}]}]}'::jsonb
WHERE slug = 'information-measurement' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Степень с натуральным показателем","blocks":[{"type":"formula","tex":"a^n = \\underbrace{a \\cdot a \\cdot \\ldots \\cdot a}_{n}"},{"type":"list","items":["$a$ — основание, $n$ — показатель.","$a^1 = a$, $a^0 = 1$ при $a \\ne 0$. Выражение $0^0$ не определено.","Отрицательное основание: чётная степень даёт плюс, нечётная — минус. $(-2)^4 = 16$, $(-2)^3 = -8$."]}]},{"kicker":"Отрицательный показатель","title":"Степень «переворачивает» дробь","blocks":[{"type":"formula","tex":"a^{-n} = \\frac{1}{a^n} \\qquad \\left(\\frac{a}{b}\\right)^{-n} = \\left(\\frac{b}{a}\\right)^n"},{"type":"list","items":["$2^{-3} = \\frac{1}{8}$.","$\\left(\\frac{2}{3}\\right)^{-2} = \\left(\\frac{3}{2}\\right)^2 = \\frac{9}{4}$.","$10^{-2} = 0{,}01$."]}]},{"kicker":"Свойства","title":"Пять правил","blocks":[{"type":"formula","tex":"a^m a^n = a^{m+n} \\quad \\frac{a^m}{a^n} = a^{m-n} \\quad (a^m)^n = a^{mn}"},{"type":"formula","tex":"(ab)^n = a^n b^n \\qquad \\left(\\frac{a}{b}\\right)^n = \\frac{a^n}{b^n}"},{"type":"note","text":"Правила работают только для **одинаковых оснований** (первые три) или **одинаковых показателей** (последние два). Сначала приведи к общему основанию: $4^3 \\cdot 8 = 2^6 \\cdot 2^3 = 2^9$."}]},{"kicker":"Стандартный вид","title":"Запись больших и малых чисел","blocks":[{"type":"formula","tex":"a \\cdot 10^n,\\quad 1 \\le a < 10"},{"type":"list","items":["$45\\,000 = 4{,}5 \\cdot 10^4$.","$0{,}0032 = 3{,}2 \\cdot 10^{-3}$.","$(3 \\cdot 10^5)(4 \\cdot 10^{-2}) = 12 \\cdot 10^3 = 1{,}2 \\cdot 10^4$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["$-2^4 = -16$, а $(-2)^4 = 16$: минус без скобок не возводится.","$a^m \\cdot a^n \\ne a^{mn}$ — показатели складываются.","$(a + b)^2 \\ne a^2 + b^2$.","$2^{-3} \\ne -8$: отрицательный показатель даёт дробь, а не отрицательное число.","$2^3 \\cdot 3^2$ не равно $6^5$: основания разные."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Натурал көрсеткішті дәреже","blocks":[{"type":"formula","tex":"a^n = \\underbrace{a \\cdot a \\cdot \\ldots \\cdot a}_{n}"},{"type":"list","items":["$a$ — негіз, $n$ — көрсеткіш.","$a^1 = a$, $a \\ne 0$ болғанда $a^0 = 1$. $0^0$ өрнегі анықталмаған.","Теріс негіз: жұп дәреже плюс, тақ дәреже минус береді. $(-2)^4 = 16$, $(-2)^3 = -8$."]}]},{"kicker":"Теріс көрсеткіш","title":"Дәреже бөлшекті «аударады»","blocks":[{"type":"formula","tex":"a^{-n} = \\frac{1}{a^n} \\qquad \\left(\\frac{a}{b}\\right)^{-n} = \\left(\\frac{b}{a}\\right)^n"},{"type":"list","items":["$2^{-3} = \\frac{1}{8}$.","$\\left(\\frac{2}{3}\\right)^{-2} = \\left(\\frac{3}{2}\\right)^2 = \\frac{9}{4}$.","$10^{-2} = 0{,}01$."]}]},{"kicker":"Қасиеттері","title":"Бес ереже","blocks":[{"type":"formula","tex":"a^m a^n = a^{m+n} \\quad \\frac{a^m}{a^n} = a^{m-n} \\quad (a^m)^n = a^{mn}"},{"type":"formula","tex":"(ab)^n = a^n b^n \\qquad \\left(\\frac{a}{b}\\right)^n = \\frac{a^n}{b^n}"},{"type":"note","text":"Ережелер тек **негіздері бірдей** (алғашқы үшеуі) немесе **көрсеткіштері бірдей** (соңғы екеуі) болғанда орындалады. Алдымен ортақ негізге келтір: $4^3 \\cdot 8 = 2^6 \\cdot 2^3 = 2^9$."}]},{"kicker":"Стандарт түрі","title":"Үлкен және кіші сандарды жазу","blocks":[{"type":"formula","tex":"a \\cdot 10^n,\\quad 1 \\le a < 10"},{"type":"list","items":["$45\\,000 = 4{,}5 \\cdot 10^4$.","$0{,}0032 = 3{,}2 \\cdot 10^{-3}$.","$(3 \\cdot 10^5)(4 \\cdot 10^{-2}) = 12 \\cdot 10^3 = 1{,}2 \\cdot 10^4$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$-2^4 = -16$, ал $(-2)^4 = 16$: жақшасыз минус дәрежеге шықпайды.","$a^m \\cdot a^n \\ne a^{mn}$ — көрсеткіштер қосылады.","$(a + b)^2 \\ne a^2 + b^2$.","$2^{-3} \\ne -8$: теріс көрсеткіш теріс сан емес, бөлшек береді.","$2^3 \\cdot 3^2$ мен $6^5$ тең емес: негіздері әртүрлі."]}]}]}'::jsonb
WHERE slug = 'integer-powers' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Основные понятия","title":"Как описывают движение","blocks":[{"type":"list","items":["**Механическое движение** — изменение положения тела относительно других тел со временем.","**Система отсчёта** = тело отсчёта + система координат + часы.","**Материальная точка** — тело, размерами которого в задаче можно пренебречь (поезд на пути Алматы — Астана)."]}]},{"kicker":"Путь и перемещение","title":"Не одно и то же","blocks":[{"type":"list","items":["**Путь** $s$ — длина траектории. Скаляр, не убывает.","**Перемещение** $\\vec s$ — вектор из начальной точки в конечную.","Обошёл стадион по кругу: путь 400 м, перемещение 0.","Путь $\\ge$ модуля перемещения. Равны только при движении по прямой в одну сторону."]}]},{"kicker":"Скорость","title":"Средняя и мгновенная","blocks":[{"type":"formula","tex":"v_{\\text{ср}} = \\frac{s_{\\text{весь}}}{t_{\\text{всё}}}"},{"type":"list","items":["Средняя путевая скорость — весь путь на всё время, а не среднее арифметическое скоростей.","Половину пути со скоростью $v_1$, половину — $v_2$: $v_{\\text{ср}} = \\frac{2v_1v_2}{v_1 + v_2}$.","Перевод: $1\\ \\text{км/ч} = \\frac{1}{3{,}6}\\ \\text{м/с}$; $72\\ \\text{км/ч} = 20\\ \\text{м/с}$."]}]},{"kicker":"Относительность","title":"Сложение скоростей","blocks":[{"type":"formula","tex":"\\vec v = \\vec v_{\\text{отн}} + \\vec v_{\\text{сист}}"},{"type":"list","items":["Навстречу: скорость сближения $v_1 + v_2$.","В одну сторону: $|v_1 - v_2|$.","Лодка поперёк реки: скорости складываются по правилу треугольника, $v = \\sqrt{v_1^2 + v_2^2}$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Средняя скорость $\\ne \\frac{v_1 + v_2}{2}$, если времена разные.","Путают путь и перемещение в задачах с возвратом.","Забывают перевести км/ч в м/с.","Траектория зависит от системы отсчёта: точка колеса для водителя движется по окружности, для пешехода — нет."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Негізгі ұғымдар","title":"Қозғалысты қалай сипаттайды","blocks":[{"type":"list","items":["**Механикалық қозғалыс** — дененің басқа денелерге қатысты орнының уақыт бойынша өзгеруі.","**Санақ жүйесі** = санақ денесі + координаталар жүйесі + сағат.","**Материялық нүкте** — есепте өлшемдерін ескермеуге болатын дене (Алматы — Астана жолындағы пойыз)."]}]},{"kicker":"Жол және орын ауыстыру","title":"Бір нәрсе емес","blocks":[{"type":"list","items":["**Жол** $s$ — траекторияның ұзындығы. Скаляр, кемімейді.","**Орын ауыстыру** $\\vec s$ — бастапқы нүктеден соңғы нүктеге бағытталған вектор.","Стадионды айналып шықты: жол 400 м, орын ауыстыру 0.","Жол $\\ge$ орын ауыстыру модулі. Тек бір бағытта түзу бойымен қозғалғанда тең."]}]},{"kicker":"Жылдамдық","title":"Орташа және лездік","blocks":[{"type":"formula","tex":"v_{\\text{орт}} = \\frac{s_{\\text{бүкіл}}}{t_{\\text{бүкіл}}}"},{"type":"list","items":["Орташа жол жылдамдығы — бүкіл жолдың бүкіл уақытқа қатынасы, жылдамдықтардың арифметикалық ортасы емес.","Жолдың жартысын $v_1$, жартысын $v_2$ жылдамдықпен: $v_{\\text{орт}} = \\frac{2v_1v_2}{v_1 + v_2}$.","Аудару: $1\\ \\text{км/сағ} = \\frac{1}{3{,}6}\\ \\text{м/с}$; $72\\ \\text{км/сағ} = 20\\ \\text{м/с}$."]}]},{"kicker":"Салыстырмалылық","title":"Жылдамдықтарды қосу","blocks":[{"type":"formula","tex":"\\vec v = \\vec v_{\\text{сал}} + \\vec v_{\\text{жүйе}}"},{"type":"list","items":["Қарама-қарсы: жақындау жылдамдығы $v_1 + v_2$.","Бір бағытта: $|v_1 - v_2|$.","Өзенді көлденең кесіп өткен қайық: жылдамдықтар үшбұрыш ережесімен қосылады, $v = \\sqrt{v_1^2 + v_2^2}$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Уақыттар әртүрлі болса, орташа жылдамдық $\\ne \\frac{v_1 + v_2}{2}$.","Қайтып келетін есептерде жол мен орын ауыстыруды шатастырады.","км/сағ-ты м/с-қа аударуды ұмытады.","Траектория санақ жүйесіне тәуелді: дөңгелектің нүктесі жүргізуші үшін шеңбермен қозғалады, жаяу адам үшін — жоқ."]}]}]}'::jsonb
WHERE slug = 'kinematics-basics' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Вид","title":"Линейное уравнение","blocks":[{"type":"formula","tex":"ax = b"},{"type":"list","items":["$a \\ne 0$: один корень $x = \\frac{b}{a}$.","$a = 0$, $b = 0$: корней бесконечно много ($0 \\cdot x = 0$).","$a = 0$, $b \\ne 0$: корней нет ($0 \\cdot x = 5$)."]}]},{"kicker":"Алгоритм","title":"Как решать","blocks":[{"type":"list","items":["Раскрой скобки.","Если есть дроби — умножь обе части на общий знаменатель.","Перенеси слагаемые с $x$ влево, числа вправо, **меняя знак**.","Приведи подобные и раздели на коэффициент при $x$."],"ordered":true},{"type":"note","text":"$\\frac{x - 1}{3} - \\frac{x}{2} = 1$ → умножаем на 6: $2x - 2 - 3x = 6$ → $-x = 8$ → $x = -8$."}]},{"kicker":"С параметром","title":"Когда в уравнении есть буква","blocks":[{"type":"text","text":"Уравнение $(a - 2)x = a^2 - 4$:"},{"type":"list","items":["$a \\ne 2$: $x = \\frac{(a - 2)(a + 2)}{a - 2} = a + 2$.","$a = 2$: $0 \\cdot x = 0$, любое $x$ — корень."]},{"type":"note","text":"Всегда отдельно проверяй значение параметра, при котором коэффициент при $x$ равен нулю."}]},{"kicker":"С модулем","title":"Уравнение $|ax + b| = c$","blocks":[{"type":"list","items":["$c < 0$: корней нет.","$c = 0$: $ax + b = 0$.","$c > 0$: $ax + b = c$ или $ax + b = -c$ — два корня."]},{"type":"note","text":"$|2x - 3| = 5$: $2x - 3 = 5 \\Rightarrow x = 4$; $2x - 3 = -5 \\Rightarrow x = -1$."}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["При переносе через знак «=» забывают сменить знак.","Умножают на знаменатель не все слагаемые, а только дроби.","Минус перед дробью относится ко всему числителю: $-\\frac{x - 1}{3}$ → $-x + 1$.","Делят на выражение с переменной и теряют корень."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Түрі","title":"Сызықтық теңдеу","blocks":[{"type":"formula","tex":"ax = b"},{"type":"list","items":["$a \\ne 0$: бір түбір $x = \\frac{b}{a}$.","$a = 0$, $b = 0$: түбірлері шексіз көп ($0 \\cdot x = 0$).","$a = 0$, $b \\ne 0$: түбірі жоқ ($0 \\cdot x = 5$)."]}]},{"kicker":"Алгоритм","title":"Қалай шешу керек","blocks":[{"type":"list","items":["Жақшаларды аш.","Бөлшектер болса, екі жағын ортақ бөлімге көбейт.","$x$-і бар қосылғыштарды солға, сандарды оңға **таңбасын өзгертіп** көшір.","Ұқсас мүшелерді келтіріп, $x$-тің коэффициентіне бөл."],"ordered":true},{"type":"note","text":"$\\frac{x - 1}{3} - \\frac{x}{2} = 1$ → 6-ға көбейтеміз: $2x - 2 - 3x = 6$ → $-x = 8$ → $x = -8$."}]},{"kicker":"Параметрмен","title":"Теңдеуде әріп болғанда","blocks":[{"type":"text","text":"$(a - 2)x = a^2 - 4$ теңдеуі:"},{"type":"list","items":["$a \\ne 2$: $x = \\frac{(a - 2)(a + 2)}{a - 2} = a + 2$.","$a = 2$: $0 \\cdot x = 0$, кез келген $x$ — түбір."]},{"type":"note","text":"$x$-тің коэффициенті нөлге тең болатын параметр мәнін әрқашан бөлек тексер."}]},{"kicker":"Модульмен","title":"$|ax + b| = c$ теңдеуі","blocks":[{"type":"list","items":["$c < 0$: түбірі жоқ.","$c = 0$: $ax + b = 0$.","$c > 0$: $ax + b = c$ немесе $ax + b = -c$ — екі түбір."]},{"type":"note","text":"$|2x - 3| = 5$: $2x - 3 = 5 \\Rightarrow x = 4$; $2x - 3 = -5 \\Rightarrow x = -1$."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["«=» белгісі арқылы көшіргенде таңбаны өзгертуді ұмытады.","Бөлімге барлық қосылғыштарды емес, тек бөлшектерді көбейтеді.","Бөлшек алдындағы минус бүкіл алымға қатысты: $-\\frac{x - 1}{3}$ → $-x + 1$.","Айнымалысы бар өрнекке бөліп, түбірді жоғалтады."]}]}]}'::jsonb
WHERE slug = 'linear-equations' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Логарифм — это показатель степени","blocks":[{"type":"formula","tex":"\\log_a b = c \\iff a^c = b"},{"type":"list","items":["Условия: $a > 0$, $a \\ne 1$, $b > 0$.","$\\log_2 8 = 3$, потому что $2^3 = 8$.","$\\log_3 \\frac{1}{9} = -2$, потому что $3^{-2} = \\frac{1}{9}$.","$\\lg b = \\log_{10} b$, $\\ln b = \\log_e b$."]}]},{"kicker":"Основные равенства","title":"Запомни сразу","blocks":[{"type":"formula","tex":"a^{\\log_a b} = b \\qquad \\log_a a = 1 \\qquad \\log_a 1 = 0"},{"type":"list","items":["$5^{\\log_5 7} = 7$.","$\\log_a a^k = k$: $\\log_2 32 = 5$."]},{"type":"note","text":"Основное логарифмическое тождество $a^{\\log_a b} = b$ часто прячется в задаче: $4^{\\log_2 3} = (2^{\\log_2 3})^2 = 9$."}]},{"kicker":"Свойства","title":"Сумма, разность, степень","blocks":[{"type":"formula","tex":"\\log_a (xy) = \\log_a x + \\log_a y \\qquad \\log_a \\frac{x}{y} = \\log_a x - \\log_a y"},{"type":"formula","tex":"\\log_a x^k = k \\log_a x \\qquad \\log_{a^k} x = \\frac{1}{k} \\log_a x"},{"type":"list","items":["$\\log_6 4 + \\log_6 9 = \\log_6 36 = 2$.","$\\log_3 54 - \\log_3 2 = \\log_3 27 = 3$.","$\\log_8 2 = \\log_{2^3} 2 = \\frac{1}{3}$."]}]},{"kicker":"Переход к другому основанию","title":"Когда основания разные","blocks":[{"type":"formula","tex":"\\log_a b = \\frac{\\log_c b}{\\log_c a} \\qquad \\log_a b = \\frac{1}{\\log_b a}"},{"type":"list","items":["$\\log_4 8 = \\frac{\\log_2 8}{\\log_2 4} = \\frac{3}{2}$.","$\\log_2 3 \\cdot \\log_3 2 = 1$.","Цепочка: $\\log_2 3 \\cdot \\log_3 4 = \\log_2 4 = 2$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["$\\log_a (x + y) \\ne \\log_a x + \\log_a y$ — сумма логарифмов это логарифм произведения.","$\\frac{\\log_a x}{\\log_a y} \\ne \\log_a \\frac{x}{y}$ — это $\\log_y x$.","$(\\log_a x)^2 \\ne 2\\log_a x$ — степень снаружи не выносится.","Под логарифмом только положительное число: $\\log_2(-4)$ не существует."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Логарифм — бұл дәреже көрсеткіші","blocks":[{"type":"formula","tex":"\\log_a b = c \\iff a^c = b"},{"type":"list","items":["Шарттар: $a > 0$, $a \\ne 1$, $b > 0$.","$\\log_2 8 = 3$, себебі $2^3 = 8$.","$\\log_3 \\frac{1}{9} = -2$, себебі $3^{-2} = \\frac{1}{9}$.","$\\lg b = \\log_{10} b$, $\\ln b = \\log_e b$."]}]},{"kicker":"Негізгі теңдіктер","title":"Бірден жатта","blocks":[{"type":"formula","tex":"a^{\\log_a b} = b \\qquad \\log_a a = 1 \\qquad \\log_a 1 = 0"},{"type":"list","items":["$5^{\\log_5 7} = 7$.","$\\log_a a^k = k$: $\\log_2 32 = 5$."]},{"type":"note","text":"Негізгі логарифмдік тепе-теңдік $a^{\\log_a b} = b$ есепте жиі жасырынып тұрады: $4^{\\log_2 3} = (2^{\\log_2 3})^2 = 9$."}]},{"kicker":"Қасиеттері","title":"Қосынды, айырым, дәреже","blocks":[{"type":"formula","tex":"\\log_a (xy) = \\log_a x + \\log_a y \\qquad \\log_a \\frac{x}{y} = \\log_a x - \\log_a y"},{"type":"formula","tex":"\\log_a x^k = k \\log_a x \\qquad \\log_{a^k} x = \\frac{1}{k} \\log_a x"},{"type":"list","items":["$\\log_6 4 + \\log_6 9 = \\log_6 36 = 2$.","$\\log_3 54 - \\log_3 2 = \\log_3 27 = 3$.","$\\log_8 2 = \\log_{2^3} 2 = \\frac{1}{3}$."]}]},{"kicker":"Басқа негізге көшу","title":"Негіздері әртүрлі болғанда","blocks":[{"type":"formula","tex":"\\log_a b = \\frac{\\log_c b}{\\log_c a} \\qquad \\log_a b = \\frac{1}{\\log_b a}"},{"type":"list","items":["$\\log_4 8 = \\frac{\\log_2 8}{\\log_2 4} = \\frac{3}{2}$.","$\\log_2 3 \\cdot \\log_3 2 = 1$.","Тізбек: $\\log_2 3 \\cdot \\log_3 4 = \\log_2 4 = 2$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$\\log_a (x + y) \\ne \\log_a x + \\log_a y$ — логарифмдер қосындысы көбейтіндінің логарифмі.","$\\frac{\\log_a x}{\\log_a y} \\ne \\log_a \\frac{x}{y}$ — бұл $\\log_y x$.","$(\\log_a x)^2 \\ne 2\\log_a x$ — сырттағы дәреже алдына шықпайды.","Логарифм астында тек оң сан: $\\log_2(-4)$ жоқ."]}]}]}'::jsonb
WHERE slug = 'logarithm-properties' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Высказывания","title":"Истина и ложь","blocks":[{"type":"text","text":"**Высказывание** — утверждение, о котором можно сказать, истинно оно (1) или ложно (0). «Астана — столица Казахстана» — истина. «Который час?» — не высказывание."},{"type":"list","items":["$\\lnot A$ — отрицание (НЕ).","$A \\land B$ — конъюнкция (И).","$A \\lor B$ — дизъюнкция (ИЛИ).","$A \\to B$ — импликация (ЕСЛИ … ТО).","$A \\equiv B$ — эквивалентность (ТОГДА И ТОЛЬКО ТОГДА)."]}]},{"kicker":"Таблицы истинности","title":"Когда операция истинна","blocks":[{"type":"list","items":["$\\lnot A$ = 1, только если $A$ = 0.","$A \\land B$ = 1, только если оба равны 1.","$A \\lor B$ = 0, только если оба равны 0.","$A \\to B$ = 0, только если $A$ = 1, $B$ = 0 («из истины ложь не следует»).","$A \\equiv B$ = 1, если значения одинаковы."]}]},{"kicker":"Порядок","title":"Приоритет операций","blocks":[{"type":"list","items":["Скобки.","Отрицание $\\lnot$.","Конъюнкция $\\land$.","Дизъюнкция $\\lor$.","Импликация $\\to$, затем эквивалентность $\\equiv$."],"ordered":true},{"type":"note","text":"$A \\lor B \\land \\lnot C$ при $A = 0, B = 1, C = 0$: $\\lnot C = 1$, $B \\land 1 = 1$, $0 \\lor 1 = 1$."}]},{"kicker":"Таблица","title":"Сколько строк","blocks":[{"type":"list","items":["Для $n$ переменных — $2^n$ строк.","3 переменные — 8 строк, 4 — 16.","Перебирай наборы как двоичные числа: 000, 001, 010, …"]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Импликация $0 \\to 0$ и $0 \\to 1$ — истинны.","Конъюнкция выполняется раньше дизъюнкции, даже если записана правее.","Отрицание суммы: $\\lnot(A \\lor B) = \\lnot A \\land \\lnot B$, а не $\\lnot A \\lor \\lnot B$.","Путают $\\land$ (И) и $\\lor$ (ИЛИ) по внешнему виду: $\\land$ похоже на букву «Л» — «и Л»."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Пікірлер","title":"Ақиқат және жалған","blocks":[{"type":"text","text":"**Пікір** — ақиқат (1) немесе жалған (0) екенін айтуға болатын тұжырым. «Астана — Қазақстанның астанасы» — ақиқат. «Сағат неше?» — пікір емес."},{"type":"list","items":["$\\lnot A$ — терістеу (ЕМЕС).","$A \\land B$ — конъюнкция (ЖӘНЕ).","$A \\lor B$ — дизъюнкция (НЕМЕСЕ).","$A \\to B$ — импликация (ЕГЕР … ОНДА).","$A \\equiv B$ — эквиваленттік (СОНДА ЖӘНЕ ТЕК СОНДА)."]}]},{"kicker":"Ақиқаттық кестелері","title":"Амал қашан ақиқат","blocks":[{"type":"list","items":["$\\lnot A$ = 1, тек $A$ = 0 болса.","$A \\land B$ = 1, тек екеуі де 1 болса.","$A \\lor B$ = 0, тек екеуі де 0 болса.","$A \\to B$ = 0, тек $A$ = 1, $B$ = 0 болса («ақиқаттан жалған шықпайды»).","$A \\equiv B$ = 1, мәндері бірдей болса."]}]},{"kicker":"Реті","title":"Амалдардың басымдығы","blocks":[{"type":"list","items":["Жақшалар.","Терістеу $\\lnot$.","Конъюнкция $\\land$.","Дизъюнкция $\\lor$.","Импликация $\\to$, содан кейін эквиваленттік $\\equiv$."],"ordered":true},{"type":"note","text":"$A = 0, B = 1, C = 0$ болғанда $A \\lor B \\land \\lnot C$: $\\lnot C = 1$, $B \\land 1 = 1$, $0 \\lor 1 = 1$."}]},{"kicker":"Кесте","title":"Неше жол","blocks":[{"type":"list","items":["$n$ айнымалы үшін — $2^n$ жол.","3 айнымалы — 8 жол, 4 — 16.","Жиындарды екілік сандар сияқты қарап шық: 000, 001, 010, …"]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$0 \\to 0$ және $0 \\to 1$ импликациялары — ақиқат.","Конъюнкция оңырақ жазылса да, дизъюнкциядан бұрын орындалады.","Қосындының терістеуі: $\\lnot(A \\lor B) = \\lnot A \\land \\lnot B$, $\\lnot A \\lor \\lnot B$ емес.","$\\land$ (ЖӘНЕ) мен $\\lor$ (НЕМЕСЕ) таңбаларын сыртқы түрі бойынша шатастырады."]}]}]}'::jsonb
WHERE slug = 'logic-operations' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Импульс тела","blocks":[{"type":"formula","tex":"\\vec p = m\\vec v \\qquad [p] = \\text{кг} \\cdot \\text{м/с}"},{"type":"list","items":["Вектор, направлен как скорость.","Изменение импульса: $\\Delta\\vec p = \\vec F\\Delta t$ — импульс силы.","Мяч отскочил от стены с той же скоростью: $|\\Delta p| = 2mv$, а не 0."]}]},{"kicker":"Закон сохранения","title":"Замкнутая система","blocks":[{"type":"formula","tex":"m_1\\vec v_1 + m_2\\vec v_2 = m_1\\vec v_1'' + m_2\\vec v_2''"},{"type":"list","items":["Сумма импульсов тел замкнутой системы не меняется.","Работает и когда внешние силы малы по сравнению с внутренними (взрыв, удар).","Записывай в проекциях на ось и следи за знаками."]}]},{"kicker":"Типичные задачи","title":"Сцепка, выстрел, прыжок","blocks":[{"type":"list","items":["Неупругий удар (тела слиплись): $m_1v_1 + m_2v_2 = (m_1 + m_2)v$.","Выстрел из покоящегося орудия: $0 = mv - Mu$, $u = \\frac{mv}{M}$ — отдача.","Человек спрыгнул с тележки: импульс до = сумма импульсов после."]},{"type":"note","text":"Реактивное движение — тоже закон сохранения импульса: газ летит назад, ракета — вперёд."}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Импульс — вектор: тела, движущиеся навстречу, вычитают импульсы.","При отскоке в противоположную сторону с той же скоростью модуль изменения импульса равен $2mv$.","Кинетическая энергия при неупругом ударе **не** сохраняется, импульс — сохраняется.","Масса в граммах — переведи в килограммы."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Дене импульсі","blocks":[{"type":"formula","tex":"\\vec p = m\\vec v \\qquad [p] = \\text{кг} \\cdot \\text{м/с}"},{"type":"list","items":["Вектор, жылдамдық бағытымен бағытталған.","Импульстің өзгерісі: $\\Delta\\vec p = \\vec F\\Delta t$ — күш импульсі.","Доп қабырғадан сол жылдамдықпен серпілді: $|\\Delta p| = 2mv$, 0 емес."]}]},{"kicker":"Сақталу заңы","title":"Тұйық жүйе","blocks":[{"type":"formula","tex":"m_1\\vec v_1 + m_2\\vec v_2 = m_1\\vec v_1'' + m_2\\vec v_2''"},{"type":"list","items":["Тұйық жүйе денелерінің импульстерінің қосындысы өзгермейді.","Сыртқы күштер ішкі күштерден әлдеқайда аз болғанда да орындалады (жарылыс, соқтығысу).","Оське проекциялармен жаз және таңбаларды қадағала."]}]},{"kicker":"Типтік есептер","title":"Тіркесу, ату, секіру","blocks":[{"type":"list","items":["Серпімсіз соқтығысу (денелер жабысты): $m_1v_1 + m_2v_2 = (m_1 + m_2)v$.","Тыныш тұрған зеңбіректен ату: $0 = mv - Mu$, $u = \\frac{mv}{M}$ — кері серпілу.","Адам арбадан секірді: бұрынғы импульс = кейінгі импульстер қосындысы."]},{"type":"note","text":"Реактивті қозғалыс — да импульстің сақталу заңы: газ артқа, зымыран алға ұшады."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Импульс — вектор: қарама-қарсы қозғалатын денелердің импульстері азайтылады.","Дене жылдамдық модулін сақтап, кері бағытқа серпілсе, импульс өзгерісінің модулі $2mv$ болады.","Серпімсіз соқтығысуда кинетикалық энергия **сақталмайды**, импульс — сақталады.","Масса граммен берілсе — килограмға аудар."]}]}]}'::jsonb
WHERE slug = 'momentum' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Основание","title":"Позиционная система счисления","blocks":[{"type":"text","text":"Значение цифры зависит от её позиции. Основание $q$ — число цифр: в двоичной 0 и 1, в восьмеричной 0–7, в шестнадцатеричной 0–9 и A–F."},{"type":"formula","tex":"\\overline{a_n \\ldots a_1 a_0}_q = a_n q^n + \\ldots + a_1 q + a_0"},{"type":"note","text":"$1011_2 = 8 + 0 + 2 + 1 = 11$. $2F_{16} = 2 \\cdot 16 + 15 = 47$."}]},{"kicker":"Из десятичной","title":"Деление с остатком","blocks":[{"type":"list","items":["Дели число на $q$, записывай остаток.","Дели частное снова, пока не получишь 0.","Читай остатки **снизу вверх**."],"ordered":true},{"type":"note","text":"$25 \\to$ двоичная: $25 = 2 \\cdot 12 + 1$, $12 = 2 \\cdot 6 + 0$, $6 = 2 \\cdot 3 + 0$, $3 = 2 \\cdot 1 + 1$, $1 = 2 \\cdot 0 + 1$ → $11001_2$."}]},{"kicker":"Двоичная ↔ 8 и 16","title":"Группы по 3 и 4 бита","blocks":[{"type":"list","items":["Восьмеричная цифра = 3 двоичных: $7_8 = 111_2$.","Шестнадцатеричная цифра = 4 двоичных: $A_{16} = 1010_2$, $F_{16} = 1111_2$.","Группируй **справа налево**, слева дополняй нулями: $1011101_2 = 001\\,011\\,101 = 135_8$."]}]},{"kicker":"Полезное","title":"Что помнить","blocks":[{"type":"list","items":["Степени двойки: $2^{10} = 1024$.","$2^n$ в двоичной — 1 и $n$ нулей; $2^n - 1$ — $n$ единиц.","Чётное число в двоичной оканчивается на 0.","Число цифр в двоичной записи $N$: $\\lfloor\\log_2 N\\rfloor + 1$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Читают остатки сверху вниз.","Цифра 8 в восьмеричной записи невозможна.","Группируют биты слева направо без дополнения нулями.","Забывают, что $A = 10$, $B = 11$, …, $F = 15$."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Негіз","title":"Позициялық санау жүйесі","blocks":[{"type":"text","text":"Цифрдың мәні оның орнына тәуелді. $q$ негіз — цифрлар саны: екілікте 0 және 1, сегіздікте 0–7, он алтылықта 0–9 және A–F."},{"type":"formula","tex":"\\overline{a_n \\ldots a_1 a_0}_q = a_n q^n + \\ldots + a_1 q + a_0"},{"type":"note","text":"$1011_2 = 8 + 0 + 2 + 1 = 11$. $2F_{16} = 2 \\cdot 16 + 15 = 47$."}]},{"kicker":"Ондықтан","title":"Қалдықпен бөлу","blocks":[{"type":"list","items":["Санды $q$-ға бөліп, қалдықты жаз.","0 шыққанша бөлінді қайта бөл.","Қалдықтарды **төменнен жоғары** оқы."],"ordered":true},{"type":"note","text":"$25 \\to$ екілік: $25 = 2 \\cdot 12 + 1$, $12 = 2 \\cdot 6 + 0$, $6 = 2 \\cdot 3 + 0$, $3 = 2 \\cdot 1 + 1$, $1 = 2 \\cdot 0 + 1$ → $11001_2$."}]},{"kicker":"Екілік ↔ 8 және 16","title":"3 және 4 биттік топтар","blocks":[{"type":"list","items":["Сегіздік цифр = 3 екілік цифр: $7_8 = 111_2$.","Он алтылық цифр = 4 екілік цифр: $A_{16} = 1010_2$, $F_{16} = 1111_2$.","**Оңнан солға** топта, сол жағын нөлмен толықтыр: $1011101_2 = 001\\,011\\,101 = 135_8$."]}]},{"kicker":"Пайдалы","title":"Нені есте сақтау керек","blocks":[{"type":"list","items":["Екінің дәрежелері: $2^{10} = 1024$.","$2^n$ екілікте — 1 және $n$ нөл; $2^n - 1$ — $n$ бірлік.","Жұп сан екілікте 0-мен аяқталады.","$N$ санының екілік жазбасындағы цифрлар саны: $\\lfloor\\log_2 N\\rfloor + 1$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Қалдықтарды жоғарыдан төмен оқиды.","Сегіздік жазбада 8 цифры болмайды.","Биттерді нөлмен толықтырмай солдан оңға топтайды.","$A = 10$, $B = 11$, …, $F = 15$ екенін ұмытады."]}]}]}'::jsonb
WHERE slug = 'positional-systems' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Давление","title":"Сила на единицу площади","blocks":[{"type":"formula","tex":"p = \\frac{F}{S} \\qquad [p] = \\text{Па} = \\text{Н/м}^2"},{"type":"list","items":["Чем меньше площадь, тем больше давление: нож, кнопка.","$1$ кПа $= 10^3$ Па, $1$ см² $= 10^{-4}$ м²."]}]},{"kicker":"Жидкость","title":"Гидростатическое давление","blocks":[{"type":"formula","tex":"p = \\rho g h"},{"type":"list","items":["Зависит только от глубины и плотности, не от формы сосуда.","Плотность воды $1000$ кг/м³: на глубине 10 м давление воды $10^5$ Па.","Полное давление на глубине: $p = p_{\\text{атм}} + \\rho g h$."]}]},{"kicker":"Закон Паскаля","title":"Давление передаётся во все стороны","blocks":[{"type":"text","text":"Давление на жидкость или газ передаётся без изменения в каждую точку."},{"type":"formula","tex":"\\frac{F_1}{S_1} = \\frac{F_2}{S_2}"},{"type":"list","items":["Гидравлический пресс даёт выигрыш в силе $\\frac{S_2}{S_1}$ раз.","Выигрыша в работе нет: малый поршень проходит больший путь."]}]},{"kicker":"Сообщающиеся сосуды","title":"Уровни жидкостей","blocks":[{"type":"list","items":["Одна жидкость — уровни одинаковы.","Разные жидкости: $\\rho_1 h_1 = \\rho_2 h_2$ — высота столба обратна плотности.","Атмосферное давление $\\approx 10^5$ Па $= 760$ мм рт. ст."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Площадь в см² не перевели в м².","Глубину считают от дна, а не от поверхности.","Давление жидкости не зависит от площади дна и формы сосуда.","Пресс выигрывает в силе, но не в работе."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Қысым","title":"Бірлік ауданға түсетін күш","blocks":[{"type":"formula","tex":"p = \\frac{F}{S} \\qquad [p] = \\text{Па} = \\text{Н/м}^2"},{"type":"list","items":["Аудан неғұрлым аз болса, қысым соғұрлым үлкен: пышақ, жапсырма шеге.","$1$ кПа $= 10^3$ Па, $1$ см² $= 10^{-4}$ м²."]}]},{"kicker":"Сұйық","title":"Гидростатикалық қысым","blocks":[{"type":"formula","tex":"p = \\rho g h"},{"type":"list","items":["Ыдыстың пішініне емес, тек тереңдік пен тығыздыққа тәуелді.","Судың тығыздығы $1000$ кг/м³: 10 м тереңдікте су қысымы $10^5$ Па.","Тереңдіктегі толық қысым: $p = p_{\\text{атм}} + \\rho g h$."]}]},{"kicker":"Паскаль заңы","title":"Қысым барлық бағытта беріледі","blocks":[{"type":"text","text":"Сұйыққа не газға түсірілген қысым әр нүктеге өзгеріссіз беріледі."},{"type":"formula","tex":"\\frac{F_1}{S_1} = \\frac{F_2}{S_2}"},{"type":"list","items":["Гидравликалық пресс күштен $\\frac{S_2}{S_1}$ есе ұтыс береді.","Жұмыстан ұтыс жоқ: кіші поршень үлкенірек жол жүреді."]}]},{"kicker":"Қатынас ыдыстар","title":"Сұйықтардың деңгейлері","blocks":[{"type":"list","items":["Бір сұйық — деңгейлер бірдей.","Әртүрлі сұйықтар: $\\rho_1 h_1 = \\rho_2 h_2$ — баған биіктігі тығыздыққа кері.","Атмосфералық қысым $\\approx 10^5$ Па $= 760$ мм сын. бағ."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["см²-ты м²-қа аудармаған.","Тереңдікті беттен емес, түбінен санайды.","Сұйық қысымы ыдыс түбінің ауданына және пішініне тәуелсіз.","Пресс күштен ұтады, жұмыстан — жоқ."]}]}]}'::jsonb
WHERE slug = 'pressure-pascal' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Переменные","title":"Значения и типы","blocks":[{"type":"list","items":["`x = 5` — присваивание: в переменную `x` записали 5.","Типы: `int` (целое), `float` (дробное), `str` (строка), `bool` (`True`/`False`).","`type(3.0)` → `float`. `int(''7'')` → 7, `str(7)` → `''7''`.","Имена чувствительны к регистру: `a` и `A` — разные переменные."]}]},{"kicker":"Ввод и вывод","title":"input и print","blocks":[{"type":"list","items":["`input()` всегда возвращает **строку**: `n = int(input())`.","`print(a, b)` выводит через пробел.","`print(a, b, sep='''')` — без пробела; `end=''''` — без перевода строки."]}]},{"kicker":"Арифметика","title":"Операции","blocks":[{"type":"list","items":["`+ - *` — как обычно; `/` — деление, результат всегда `float`: `7 / 2` → `3.5`.","`//` — целочисленное деление: `7 // 2` → `3`, `-7 // 2` → `-4` (округление вниз).","`%` — остаток: `7 % 2` → `1`, `-7 % 2` → `1`.","`**` — степень: `2 ** 10` → `1024`."]},{"type":"note","text":"Последняя цифра числа `n`: `n % 10`. Число без последней цифры: `n // 10`."}]},{"kicker":"Строки","title":"Работа с текстом","blocks":[{"type":"list","items":["`''ab'' + ''cd''` → `''abcd''`; `''ab'' * 3` → `''ababab''`.","`len(''Алем'')` → 4.","Индексы с нуля: `s[0]` — первый символ, `s[-1]` — последний.","Срез `s[1:4]` — символы с 1-го по 3-й (правая граница не входит)."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["`input()` без `int()` — сложение строк: `''2'' + ''3''` → `''23''`.","`/` даёт `float` даже при делении нацело: `6 / 3` → `2.0`.","`//` с отрицательными числами округляет вниз, а не к нулю.","Срез не включает правую границу."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Айнымалылар","title":"Мәндер және типтер","blocks":[{"type":"list","items":["`x = 5` — меншіктеу: `x` айнымалысына 5 жазылды.","Типтер: `int` (бүтін), `float` (бөлшек), `str` (жол), `bool` (`True`/`False`).","`type(3.0)` → `float`. `int(''7'')` → 7, `str(7)` → `''7''`.","Атаулар регистрге сезімтал: `a` мен `A` — әртүрлі айнымалылар."]}]},{"kicker":"Енгізу және шығару","title":"input және print","blocks":[{"type":"list","items":["`input()` әрқашан **жол** қайтарады: `n = int(input())`.","`print(a, b)` бос орын арқылы шығарады.","`print(a, b, sep='''')` — бос орынсыз; `end=''''` — жаңа жолға көшпей."]}]},{"kicker":"Арифметика","title":"Амалдар","blocks":[{"type":"list","items":["`+ - *` — әдеттегідей; `/` — бөлу, нәтиже әрқашан `float`: `7 / 2` → `3.5`.","`//` — бүтін бөлу: `7 // 2` → `3`, `-7 // 2` → `-4` (төмен дөңгелектеу).","`%` — қалдық: `7 % 2` → `1`, `-7 % 2` → `1`.","`**` — дәреже: `2 ** 10` → `1024`."]},{"type":"note","text":"`n` санының соңғы цифры: `n % 10`. Соңғы цифрсыз сан: `n // 10`."}]},{"kicker":"Жолдар","title":"Мәтінмен жұмыс","blocks":[{"type":"list","items":["`''ab'' + ''cd''` → `''abcd''`; `''ab'' * 3` → `''ababab''`.","`len(''Алем'')` → 4.","Индекстер нөлден: `s[0]` — бірінші символ, `s[-1]` — соңғысы.","`s[1:4]` қимасы — 1-ден 3-ке дейінгі символдар (оң шекара кірмейді)."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["`int()`-сіз `input()` — жолдарды қосу: `''2'' + ''3''` → `''23''`.","`/` қалдықсыз бөлінсе де `float` береді: `6 / 3` → `2.0`.","`//` теріс сандарда нөлге емес, төмен дөңгелектейді.","Қима оң шекараны қамтымайды."]}]}]}'::jsonb
WHERE slug = 'python-basics' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Условный оператор","title":"if, elif, else","blocks":[{"type":"text","text":"Проверяется первое истинное условие, остальные ветки пропускаются."},{"type":"list","items":["`if x > 0:` → `print(''плюс'')`","`elif x == 0:` → `print(''ноль'')`","`else:` → `print(''минус'')`","Тело ветки выделяется **отступом** (4 пробела)."]}]},{"kicker":"Сравнения","title":"Операторы сравнения","blocks":[{"type":"list","items":["`==` равно, `!=` не равно, `<`, `>`, `<=`, `>=`.","`=` — присваивание, `==` — сравнение.","Цепочки: `0 < x < 10` — то же, что `0 < x and x < 10`.","Строки сравниваются посимвольно по кодам: `''b'' > ''a''`, `''Z'' < ''a''`."]}]},{"kicker":"Логические операции","title":"and, or, not","blocks":[{"type":"list","items":["`and` — истинно, если оба условия истинны.","`or` — если хотя бы одно.","`not` — отрицание.","Приоритет: `not`, затем `and`, затем `or`."]},{"type":"note","text":"Чётное и положительное: `if x % 2 == 0 and x > 0:`."}]},{"kicker":"Трассировка","title":"Как решать задачи «что выведет»","blocks":[{"type":"list","items":["Выпиши значения переменных.","Проверь условие с текущими значениями.","Выполни **только одну** ветку цепочки if/elif/else.","Помни: несколько отдельных `if` проверяются все, по очереди."],"ordered":true}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Выполняют несколько веток `elif` — выполняется только первая истинная.","Отдельные `if` подряд — не одна цепочка: проверяются все.","`=` вместо `==` в условии — синтаксическая ошибка.","`x % 2 == 1` для отрицательных нечётных в Python тоже верно: `-3 % 2` → `1`."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Шартты оператор","title":"if, elif, else","blocks":[{"type":"text","text":"Бірінші ақиқат шарт тексеріледі, қалған тармақтар өткізіліп жіберіледі."},{"type":"list","items":["`if x > 0:` → `print(''оң'')`","`elif x == 0:` → `print(''нөл'')`","`else:` → `print(''теріс'')`","Тармақ денесі **шегініспен** (4 бос орын) бөлінеді."]}]},{"kicker":"Салыстырулар","title":"Салыстыру операторлары","blocks":[{"type":"list","items":["`==` тең, `!=` тең емес, `<`, `>`, `<=`, `>=`.","`=` — меншіктеу, `==` — салыстыру.","Тізбек: `0 < x < 10` — `0 < x and x < 10` дегенмен бірдей.","Жолдар кодтары бойынша символдап салыстырылады: `''b'' > ''a''`, `''Z'' < ''a''`."]}]},{"kicker":"Логикалық амалдар","title":"and, or, not","blocks":[{"type":"list","items":["`and` — екі шарт та ақиқат болса, ақиқат.","`or` — кемінде біреуі ақиқат болса.","`not` — терістеу.","Басымдық: `not`, содан кейін `and`, содан кейін `or`."]},{"type":"note","text":"Жұп және оң: `if x % 2 == 0 and x > 0:`."}]},{"kicker":"Трассировка","title":"«Не шығарады» есептерін қалай шешу керек","blocks":[{"type":"list","items":["Айнымалылардың мәндерін жазып ал.","Шартты қазіргі мәндермен тексер.","if/elif/else тізбегінің **тек бір** тармағын орында.","Есте сақта: бөлек бірнеше `if` кезекпен барлығы тексеріледі."],"ordered":true}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Бірнеше `elif` тармағын орындайды — тек бірінші ақиқаты орындалады.","Қатар тұрған бөлек `if`-тер — бір тізбек емес: барлығы тексеріледі.","Шартта `==` орнына `=` — синтаксистік қате.","Python-да теріс тақ сандар үшін де `x % 2 == 1` орындалады: `-3 % 2` → `1`."]}]}]}'::jsonb
WHERE slug = 'python-branching' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Цикл for","title":"Повторение по диапазону","blocks":[{"type":"list","items":["`for i in range(5):` — `i` = 0, 1, 2, 3, 4 (пять раз).","`range(a, b)` — от `a` до `b - 1`.","`range(a, b, s)` — с шагом `s`: `range(1, 10, 3)` → 1, 4, 7.","`range(10, 0, -2)` → 10, 8, 6, 4, 2."]}]},{"kicker":"Цикл while","title":"Повторение, пока условие истинно","blocks":[{"type":"list","items":["`while n > 0:` → `n = n // 10`","Условие проверяется **перед** каждым шагом.","Если условие сразу ложно — тело не выполнится ни разу.","Если условие не станет ложным — бесконечный цикл."]},{"type":"note","text":"Сумма цифр: `s = 0`; `while n > 0: s += n % 10; n //= 10`."}]},{"kicker":"Управление","title":"break и continue","blocks":[{"type":"list","items":["`break` — немедленный выход из цикла.","`continue` — переход к следующему шагу, остаток тела пропускается.","Во вложенных циклах `break` выходит только из внутреннего."]}]},{"kicker":"Подсчёт","title":"Сколько раз выполнится тело","blocks":[{"type":"list","items":["`range(a, b)` — $b - a$ раз (если $b > a$).","`range(a, b, s)` — $\\lceil (b - a) / s \\rceil$ раз.","Вложенные циклы `for i in range(n)` и `for j in range(m)` — $n \\cdot m$ раз.","`for j in range(i, n)` внутри `for i in range(n)` — $\\frac{n(n + 1)}{2}$ раз."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["`range(1, 10)` не включает 10.","Значение переменной цикла после `for` — последнее из диапазона, а не следующее.","В `while` забывают изменить переменную условия.","Отступ: строка без отступа после цикла выполняется один раз, после цикла."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"for циклі","title":"Аралық бойынша қайталау","blocks":[{"type":"list","items":["`for i in range(5):` — `i` = 0, 1, 2, 3, 4 (бес рет).","`range(a, b)` — `a`-дан `b - 1`-ге дейін.","`range(a, b, s)` — `s` қадаммен: `range(1, 10, 3)` → 1, 4, 7.","`range(10, 0, -2)` → 10, 8, 6, 4, 2."]}]},{"kicker":"while циклі","title":"Шарт ақиқат болғанша қайталау","blocks":[{"type":"list","items":["`while n > 0:` → `n = n // 10`","Шарт әр қадамның **алдында** тексеріледі.","Шарт бірден жалған болса — дене бірде-бір рет орындалмайды.","Шарт жалған болмаса — шексіз цикл."]},{"type":"note","text":"Цифрлар қосындысы: `s = 0`; `while n > 0: s += n % 10; n //= 10`."}]},{"kicker":"Басқару","title":"break және continue","blocks":[{"type":"list","items":["`break` — циклдан бірден шығу.","`continue` — келесі қадамға өту, дененің қалғаны өткізіледі.","Кірістірілген циклдарда `break` тек ішкісінен шығарады."]}]},{"kicker":"Санау","title":"Дене неше рет орындалады","blocks":[{"type":"list","items":["`range(a, b)` — $b - a$ рет ($b > a$ болса).","`range(a, b, s)` — $\\lceil (b - a) / s \\rceil$ рет.","`for i in range(n)` және `for j in range(m)` кірістірілген циклдары — $n \\cdot m$ рет.","`for i in range(n)` ішіндегі `for j in range(i, n)` — $\\frac{n(n + 1)}{2}$ рет."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["`range(1, 10)` 10-ды қамтымайды.","`for`-тан кейін цикл айнымалысының мәні — келесісі емес, аралықтың соңғысы.","`while`-та шарт айнымалысын өзгертуді ұмытады.","Шегініс: циклдан кейінгі шегініссіз жол циклдан соң бір рет орындалады."]}]}]}'::jsonb
WHERE slug = 'python-loops' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Формула","title":"Дискриминант","blocks":[{"type":"formula","tex":"ax^2 + bx + c = 0 \\qquad D = b^2 - 4ac \\qquad x_{1,2} = \\frac{-b \\pm \\sqrt{D}}{2a}"},{"type":"list","items":["$D > 0$ — два корня.","$D = 0$ — один корень $x = -\\frac{b}{2a}$.","$D < 0$ — действительных корней нет."]}]},{"kicker":"Чётный $b$","title":"Формула через $D/4$","blocks":[{"type":"formula","tex":"b = 2k:\\quad \\frac{D}{4} = k^2 - ac \\qquad x_{1,2} = \\frac{-k \\pm \\sqrt{D/4}}{a}"},{"type":"note","text":"$x^2 - 6x + 5 = 0$: $k = -3$, $\\frac{D}{4} = 9 - 5 = 4$, $x = 3 \\pm 2$, то есть $1$ и $5$. Числа меньше — ошибок меньше."}]},{"kicker":"Неполные","title":"Когда $b = 0$ или $c = 0$","blocks":[{"type":"list","items":["$ax^2 + bx = 0$: $x(ax + b) = 0$, корни $0$ и $-\\frac{b}{a}$.","$ax^2 + c = 0$: $x^2 = -\\frac{c}{a}$; если правая часть отрицательна — корней нет.","$x^2 = 9$ → $x = \\pm 3$. Не теряй минус!"]}]},{"kicker":"Быстрые приёмы","title":"Устные проверки","blocks":[{"type":"list","items":["$a + b + c = 0$ → $x_1 = 1$, $x_2 = \\frac{c}{a}$. Пример: $3x^2 - 5x + 2 = 0$ → $1$ и $\\frac{2}{3}$.","$a - b + c = 0$ → $x_1 = -1$, $x_2 = -\\frac{c}{a}$.","Замена: $x^4 - 5x^2 + 4 = 0$, $t = x^2 \\ge 0$ → $t = 1$ или $4$ → $x = \\pm 1, \\pm 2$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["$-b$ при отрицательном $b$: при $b = -7$ в числителе стоит $+7$.","Делят только $\\sqrt{D}$ на $2a$, а не всю сумму.","Делят уравнение на $x$ и теряют корень $x = 0$.","В вопросе «сумма корней» или «произведение» — не обязательно находить сами корни (теорема Виета)."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Формула","title":"Дискриминант","blocks":[{"type":"formula","tex":"ax^2 + bx + c = 0 \\qquad D = b^2 - 4ac \\qquad x_{1,2} = \\frac{-b \\pm \\sqrt{D}}{2a}"},{"type":"list","items":["$D > 0$ — екі түбір.","$D = 0$ — бір түбір $x = -\\frac{b}{2a}$.","$D < 0$ — нақты түбірлері жоқ."]}]},{"kicker":"Жұп $b$","title":"$D/4$ арқылы формула","blocks":[{"type":"formula","tex":"b = 2k:\\quad \\frac{D}{4} = k^2 - ac \\qquad x_{1,2} = \\frac{-k \\pm \\sqrt{D/4}}{a}"},{"type":"note","text":"$x^2 - 6x + 5 = 0$: $k = -3$, $\\frac{D}{4} = 9 - 5 = 4$, $x = 3 \\pm 2$, яғни $1$ және $5$. Сандар кіші — қате аз."}]},{"kicker":"Толымсыз","title":"$b = 0$ немесе $c = 0$ болғанда","blocks":[{"type":"list","items":["$ax^2 + bx = 0$: $x(ax + b) = 0$, түбірлері $0$ және $-\\frac{b}{a}$.","$ax^2 + c = 0$: $x^2 = -\\frac{c}{a}$; оң жағы теріс болса — түбірі жоқ.","$x^2 = 9$ → $x = \\pm 3$. Минусты жоғалтпа!"]}]},{"kicker":"Жылдам тәсілдер","title":"Ауызша тексерулер","blocks":[{"type":"list","items":["$a + b + c = 0$ → $x_1 = 1$, $x_2 = \\frac{c}{a}$. Мысал: $3x^2 - 5x + 2 = 0$ → $1$ және $\\frac{2}{3}$.","$a - b + c = 0$ → $x_1 = -1$, $x_2 = -\\frac{c}{a}$.","Алмастыру: $x^4 - 5x^2 + 4 = 0$, $t = x^2 \\ge 0$ → $t = 1$ немесе $4$ → $x = \\pm 1, \\pm 2$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$b$ теріс болғанда $-b$: $b = -7$ болса, алымда $+7$ тұрады.","Бүкіл қосындыны емес, тек $\\sqrt{D}$-ны $2a$-ға бөледі.","Теңдеуді $x$-ке бөліп, $x = 0$ түбірін жоғалтады.","«Түбірлер қосындысы» не «көбейтіндісі» сұралса, түбірлердің өзін табу міндетті емес (Виет теоремасы)."]}]}]}'::jsonb
WHERE slug = 'quadratic-equations' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Дробный показатель — это корень","blocks":[{"type":"formula","tex":"a^{\\frac{m}{n}} = \\sqrt[n]{a^m},\\quad a > 0"},{"type":"list","items":["$8^{\\frac{2}{3}} = \\sqrt[3]{8^2} = (\\sqrt[3]{8})^2 = 4$.","$16^{0{,}75} = 16^{\\frac{3}{4}} = 2^3 = 8$.","$27^{-\\frac{1}{3}} = \\frac{1}{3}$."]},{"type":"note","text":"Удобнее сначала извлечь корень, потом возводить в степень: числа меньше."}]},{"kicker":"Свойства","title":"Правила те же, что для целых степеней","blocks":[{"type":"formula","tex":"a^r a^s = a^{r+s} \\quad \\frac{a^r}{a^s} = a^{r-s} \\quad (a^r)^s = a^{rs}"},{"type":"list","items":["$a^{\\frac{1}{2}} \\cdot a^{\\frac{1}{3}} = a^{\\frac{5}{6}}$.","$\\sqrt{a} \\cdot \\sqrt[3]{a} = \\sqrt[6]{a^5}$ — то же самое в записи корнями.","Корни разных степеней перемножают через общий показатель."]}]},{"kicker":"Приём","title":"Всё — к степени одного основания","blocks":[{"type":"text","text":"Запиши корни как степени, приведи основания к одному числу, сложи показатели."},{"type":"list","items":["$\\frac{\\sqrt{2} \\cdot \\sqrt[4]{8}}{\\sqrt[4]{2}} = 2^{\\frac{1}{2} + \\frac{3}{4} - \\frac{1}{4}} = 2^1 = 2$.","$\\sqrt[3]{9} \\cdot \\sqrt[6]{9} = 9^{\\frac{1}{3} + \\frac{1}{6}} = 9^{\\frac{1}{2}} = 3$."]}]},{"kicker":"Сравнение","title":"Какая степень больше","blocks":[{"type":"list","items":["При $a > 1$: больше показатель — больше степень. $2^{0{,}3} < 2^{0{,}5}$.","При $0 < a < 1$ наоборот: $0{,}5^{0{,}3} > 0{,}5^{0{,}5}$.","Разные основания — приведи к одному показателю: $\\sqrt{3}$ и $\\sqrt[3]{5}$ → $\\sqrt[6]{27}$ и $\\sqrt[6]{25}$, первое больше."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["$a^{\\frac{m}{n}}$ — это $\\sqrt[n]{a^m}$, а не $\\sqrt[m]{a^n}$: знаменатель — степень корня.","Отрицательное основание с дробным показателем в школе не рассматривают.","$0{,}75 = \\frac{3}{4}$, $0{,}25 = \\frac{1}{4}$, $1{,}5 = \\frac{3}{2}$ — переводи десятичный показатель в дробь."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Бөлшек көрсеткіш — бұл түбір","blocks":[{"type":"formula","tex":"a^{\\frac{m}{n}} = \\sqrt[n]{a^m},\\quad a > 0"},{"type":"list","items":["$8^{\\frac{2}{3}} = \\sqrt[3]{8^2} = (\\sqrt[3]{8})^2 = 4$.","$16^{0{,}75} = 16^{\\frac{3}{4}} = 2^3 = 8$.","$27^{-\\frac{1}{3}} = \\frac{1}{3}$."]},{"type":"note","text":"Алдымен түбірді алып, кейін дәрежеге шығарған ыңғайлы: сандар кішірек болады."}]},{"kicker":"Қасиеттері","title":"Ережелер бүтін дәрежелердегідей","blocks":[{"type":"formula","tex":"a^r a^s = a^{r+s} \\quad \\frac{a^r}{a^s} = a^{r-s} \\quad (a^r)^s = a^{rs}"},{"type":"list","items":["$a^{\\frac{1}{2}} \\cdot a^{\\frac{1}{3}} = a^{\\frac{5}{6}}$.","$\\sqrt{a} \\cdot \\sqrt[3]{a} = \\sqrt[6]{a^5}$ — түбірмен жазылған дәл сол өрнек.","Әртүрлі дәрежелі түбірлерді ортақ көрсеткіш арқылы көбейтеді."]}]},{"kicker":"Тәсіл","title":"Бәрін бір негіздің дәрежесіне келтір","blocks":[{"type":"text","text":"Түбірлерді дәреже түрінде жаз, негіздерді бір санға келтір, көрсеткіштерді қос."},{"type":"list","items":["$\\frac{\\sqrt{2} \\cdot \\sqrt[4]{8}}{\\sqrt[4]{2}} = 2^{\\frac{1}{2} + \\frac{3}{4} - \\frac{1}{4}} = 2^1 = 2$.","$\\sqrt[3]{9} \\cdot \\sqrt[6]{9} = 9^{\\frac{1}{3} + \\frac{1}{6}} = 9^{\\frac{1}{2}} = 3$."]}]},{"kicker":"Салыстыру","title":"Қай дәреже үлкен","blocks":[{"type":"list","items":["$a > 1$ болғанда: көрсеткіш үлкен болса, дәреже де үлкен. $2^{0{,}3} < 2^{0{,}5}$.","$0 < a < 1$ болғанда керісінше: $0{,}5^{0{,}3} > 0{,}5^{0{,}5}$.","Негіздері әртүрлі болса, бір көрсеткішке келтір: $\\sqrt{3}$ және $\\sqrt[3]{5}$ → $\\sqrt[6]{27}$ және $\\sqrt[6]{25}$, біріншісі үлкен."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$a^{\\frac{m}{n}}$ — бұл $\\sqrt[n]{a^m}$, $\\sqrt[m]{a^n}$ емес: бөлім — түбірдің дәрежесі.","Теріс негізді бөлшек көрсеткішпен мектепте қарастырмайды.","$0{,}75 = \\frac{3}{4}$, $0{,}25 = \\frac{1}{4}$, $1{,}5 = \\frac{3}{2}$ — ондық көрсеткішті бөлшекке аудар."]}]}]}'::jsonb
WHERE slug = 'rational-powers' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Квадраты","title":"Квадрат суммы и разности","blocks":[{"type":"formula","tex":"(a + b)^2 = a^2 + 2ab + b^2 \\qquad (a - b)^2 = a^2 - 2ab + b^2"},{"type":"list","items":["$(x + 3)^2 = x^2 + 6x + 9$.","$(2a - 5)^2 = 4a^2 - 20a + 25$.","Устный счёт: $51^2 = (50 + 1)^2 = 2601$, $99^2 = (100 - 1)^2 = 9801$."]}]},{"kicker":"Разность квадратов","title":"Самая полезная формула","blocks":[{"type":"formula","tex":"a^2 - b^2 = (a - b)(a + b)"},{"type":"list","items":["$x^2 - 16 = (x - 4)(x + 4)$.","$47^2 - 43^2 = 4 \\cdot 90 = 360$.","$(\\sqrt{7} - \\sqrt{3})(\\sqrt{7} + \\sqrt{3}) = 7 - 3 = 4$ — так избавляются от корня в знаменателе."]}]},{"kicker":"Кубы","title":"Куб суммы и разности","blocks":[{"type":"formula","tex":"(a \\pm b)^3 = a^3 \\pm 3a^2b + 3ab^2 \\pm b^3"},{"type":"list","items":["$(x + 1)^3 = x^3 + 3x^2 + 3x + 1$.","$(a - 2)^3 = a^3 - 6a^2 + 12a - 8$."]},{"type":"note","text":"Коэффициенты 1, 3, 3, 1 — как в треугольнике Паскаля. Знаки в разности чередуются."}]},{"kicker":"Сумма и разность кубов","title":"Не путай с кубом суммы","blocks":[{"type":"formula","tex":"a^3 + b^3 = (a + b)(a^2 - ab + b^2) \\qquad a^3 - b^3 = (a - b)(a^2 + ab + b^2)"},{"type":"list","items":["$x^3 - 8 = (x - 2)(x^2 + 2x + 4)$.","$27 + y^3 = (3 + y)(9 - 3y + y^2)$.","Во второй скобке «неполный квадрат»: $ab$, а не $2ab$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["$(a + b)^2 \\ne a^2 + b^2$ — забывают удвоенное произведение.","$(a - b)^2 = (b - a)^2$, но $(a - b)^3 = -(b - a)^3$.","$a^2 + b^2$ на множители (в действительных числах) не раскладывается.","В сумме кубов во второй скобке минус: $a^2 - ab + b^2$."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Квадраттар","title":"Қосындының және айырымның квадраты","blocks":[{"type":"formula","tex":"(a + b)^2 = a^2 + 2ab + b^2 \\qquad (a - b)^2 = a^2 - 2ab + b^2"},{"type":"list","items":["$(x + 3)^2 = x^2 + 6x + 9$.","$(2a - 5)^2 = 4a^2 - 20a + 25$.","Ауызша есеп: $51^2 = (50 + 1)^2 = 2601$, $99^2 = (100 - 1)^2 = 9801$."]}]},{"kicker":"Квадраттар айырымы","title":"Ең пайдалы формула","blocks":[{"type":"formula","tex":"a^2 - b^2 = (a - b)(a + b)"},{"type":"list","items":["$x^2 - 16 = (x - 4)(x + 4)$.","$47^2 - 43^2 = 4 \\cdot 90 = 360$.","$(\\sqrt{7} - \\sqrt{3})(\\sqrt{7} + \\sqrt{3}) = 7 - 3 = 4$ — бөлімдегі түбірден осылай арылады."]}]},{"kicker":"Кубтар","title":"Қосындының және айырымның кубы","blocks":[{"type":"formula","tex":"(a \\pm b)^3 = a^3 \\pm 3a^2b + 3ab^2 \\pm b^3"},{"type":"list","items":["$(x + 1)^3 = x^3 + 3x^2 + 3x + 1$.","$(a - 2)^3 = a^3 - 6a^2 + 12a - 8$."]},{"type":"note","text":"1, 3, 3, 1 коэффициенттері — Паскаль үшбұрышындағыдай. Айырымда таңбалар кезектеседі."}]},{"kicker":"Кубтар қосындысы мен айырымы","title":"Қосындының кубымен шатастырма","blocks":[{"type":"formula","tex":"a^3 + b^3 = (a + b)(a^2 - ab + b^2) \\qquad a^3 - b^3 = (a - b)(a^2 + ab + b^2)"},{"type":"list","items":["$x^3 - 8 = (x - 2)(x^2 + 2x + 4)$.","$27 + y^3 = (3 + y)(9 - 3y + y^2)$.","Екінші жақшада «толымсыз квадрат»: $2ab$ емес, $ab$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$(a + b)^2 \\ne a^2 + b^2$ — екі еселенген көбейтіндіні ұмытады.","$(a - b)^2 = (b - a)^2$, бірақ $(a - b)^3 = -(b - a)^3$.","$a^2 + b^2$ (нақты сандарда) көбейткіштерге жіктелмейді.","Кубтар қосындысында екінші жақшада минус: $a^2 - ab + b^2$."]}]}]}'::jsonb
WHERE slug = 'short-multiplication' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Кодовые таблицы","title":"Как текст становится числами","blocks":[{"type":"list","items":["Каждому символу ставится в соответствие число — **код**.","**ASCII** — 7 бит (128 символов), расширенные однобайтные кодировки — 8 бит (до 256 кодовых позиций: CP-1251, KOI8-R).","**Unicode** — единая таблица для всех языков мира, включая казахские буквы ә, ғ, қ, ң, ө, ұ, ү, һ, і."]}]},{"kicker":"Unicode","title":"UTF-8 и UTF-16","blocks":[{"type":"list","items":["**UTF-16** использует одну или две 16-битные единицы (2 или 4 байта) на кодовую точку.","**UTF-8** использует от 1 до 4 байтов на кодовую точку. ASCII занимает 1 байт, обычные русские и казахские буквы — по 2.","Если в задаче сказано «каждый символ кодируется 16 битами» — используй это, не угадывай."]},{"type":"note","text":"Неправильная кодировка при открытии файла даёт «кракозябры»: байты прочитаны по другой таблице."}]},{"kicker":"Задачи","title":"Расчёт объёма текста","blocks":[{"type":"list","items":["Посчитай символы, включая пробелы и знаки препинания.","Умножь на число бит на символ.","Переведи в нужные единицы."],"ordered":true},{"type":"note","text":"Фраза «Я учусь!» — 8 символов. В 16-битной кодировке: $8 \\cdot 16 = 128$ бит $= 16$ байт."}]},{"kicker":"Порядок кодов","title":"Буквы идут подряд","blocks":[{"type":"list","items":["В ASCII цифры 0–9 имеют коды 48–57, буквы A–Z — 65–90, a–z — 97–122.","Код строчной латинской буквы на 32 больше заглавной.","Если код буквы «D» равен 68, то код «G» равен 71."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Не считают пробелы и знаки препинания.","Считают, что в Unicode всегда 1 байт на символ.","Путают «удалили 4 символа» и «удалили 4 байта».","Кавычки, в которых дана фраза, не входят в текст."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Код кестелері","title":"Мәтін қалай санға айналады","blocks":[{"type":"list","items":["Әр символға сан — **код** сәйкес қойылады.","**ASCII** — 7 бит (128 символ), кеңейтілген бір байтты кодтаулар — 8 бит (256-ға дейін код орны: CP-1251, KOI8-R).","**Unicode** — әлемнің барлық тілдеріне ортақ кесте, қазақтың ә, ғ, қ, ң, ө, ұ, ү, һ, і әріптері де бар."]}]},{"kicker":"Unicode","title":"UTF-8 және UTF-16","blocks":[{"type":"list","items":["**UTF-16** әр кодтық нүктеге бір немесе екі 16 биттік бірлік (2 немесе 4 байт) қолданады.","**UTF-8** әр кодтық нүктеге 1–4 байт қолданады. ASCII-ге 1 байт, орыс және қазақ әліпбиінің әріптеріне 2 байт қажет.","Есепте «әр символ 16 битпен кодталады» делінсе — соны қолдан, болжама."]},{"type":"note","text":"Файлды дұрыс емес кодтаумен ашса, «түсініксіз белгілер» шығады: байттар басқа кесте бойынша оқылды."}]},{"kicker":"Есептер","title":"Мәтін көлемін есептеу","blocks":[{"type":"list","items":["Бос орындар мен тыныс белгілерін қоса символдарды сана.","Бір символдағы бит санына көбейт.","Керекті бірлікке аудар."],"ordered":true},{"type":"note","text":"«Мен оқимын!» тіркесі — 11 символ. 16 биттік кодтауда: $11 \\cdot 16 = 176$ бит $= 22$ байт."}]},{"kicker":"Кодтар реті","title":"Әріптер қатар орналасады","blocks":[{"type":"list","items":["ASCII-де 0–9 цифрларының кодтары 48–57, A–Z әріптерінікі — 65–90, a–z — 97–122.","Кіші латын әрпінің коды бас әріптікінен 32-ге артық.","«D» әрпінің коды 68 болса, «G» әрпінің коды 71."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Бос орындар мен тыныс белгілерін санамайды.","Unicode-та бір символ әрқашан 1 байт деп ойлайды.","«4 символ өшірілді» мен «4 байт өшірілді» дегенді шатастырады.","Тіркес жазылған тырнақшалар мәтінге кірмейді."]}]}]}'::jsonb
WHERE slug = 'text-encoding' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Определение","title":"Равномерное прямолинейное движение","blocks":[{"type":"text","text":"Тело за **любые равные** промежутки времени проходит равные пути. Скорость постоянна по модулю и направлению."},{"type":"formula","tex":"x = x_0 + v_x t \\qquad s = vt"},{"type":"list","items":["$v_x > 0$ — движение по оси, $v_x < 0$ — против оси.","$x = 5 - 2t$: начальная координата 5 м, скорость $-2$ м/с."]}]},{"kicker":"Графики","title":"Как читать графики","blocks":[{"type":"list","items":["$x(t)$ — прямая. Наклон = скорость: $v = \\frac{\\Delta x}{\\Delta t}$.","$v(t)$ — горизонтальная прямая.","Площадь под графиком $v(t)$ = перемещение.","Более крутой график $x(t)$ — большая скорость."]},{"type":"note","text":"Точка пересечения графиков $x_1(t)$ и $x_2(t)$ — место и время встречи."}]},{"kicker":"Встреча","title":"Задачи на движение двух тел","blocks":[{"type":"list","items":["Запиши $x_1(t)$ и $x_2(t)$ в одной системе координат.","Приравняй: $x_1(t) = x_2(t)$ — найдёшь время встречи.","Подставь время в любое уравнение — найдёшь место."],"ordered":true},{"type":"note","text":"$x_1 = 2t$, $x_2 = 120 - 4t$: $2t = 120 - 4t$, $t = 20$ с, $x = 40$ м."}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Знак скорости: тело, едущее навстречу оси, имеет $v_x < 0$.","Разные единицы в одной задаче: км и м, ч и с.","Путь при $v_x < 0$ положителен: $s = |v| t$.","Наклон графика читают по клеткам, не проверив масштаб осей."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Анықтама","title":"Бірқалыпты түзу сызықты қозғалыс","blocks":[{"type":"text","text":"Дене **кез келген тең** уақыт аралықтарында тең жолдар жүреді. Жылдамдық модулі де, бағыты да тұрақты."},{"type":"formula","tex":"x = x_0 + v_x t \\qquad s = vt"},{"type":"list","items":["$v_x > 0$ — ось бойымен, $v_x < 0$ — оське қарсы.","$x = 5 - 2t$: бастапқы координата 5 м, жылдамдық $-2$ м/с."]}]},{"kicker":"Графиктер","title":"Графиктерді қалай оқу керек","blocks":[{"type":"list","items":["$x(t)$ — түзу. Көлбеулігі = жылдамдық: $v = \\frac{\\Delta x}{\\Delta t}$.","$v(t)$ — горизонталь түзу.","$v(t)$ графигінің астындағы аудан = орын ауыстыру.","$x(t)$ графигі тік болса — жылдамдық үлкен."]},{"type":"note","text":"$x_1(t)$ мен $x_2(t)$ графиктерінің қиылысу нүктесі — кездесу орны мен уақыты."}]},{"kicker":"Кездесу","title":"Екі дененің қозғалысына есептер","blocks":[{"type":"list","items":["$x_1(t)$ мен $x_2(t)$-ны бір координаталар жүйесінде жаз.","Теңестір: $x_1(t) = x_2(t)$ — кездесу уақытын табасың.","Уақытты кез келген теңдеуге қой — орнын табасың."],"ordered":true},{"type":"note","text":"$x_1 = 2t$, $x_2 = 120 - 4t$: $2t = 120 - 4t$, $t = 20$ с, $x = 40$ м."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Жылдамдық таңбасы: оське қарсы қозғалатын дененің $v_x < 0$.","Бір есепте әртүрлі бірліктер: км мен м, сағ пен с.","$v_x < 0$ болғанда да жол оң: $s = |v| t$.","Осьтердің масштабын тексермей, графиктің көлбеулігін тор көзімен оқиды."]}]}]}'::jsonb
WHERE slug = 'uniform-motion' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Теорема","title":"Теорема Виета","blocks":[{"type":"formula","tex":"ax^2 + bx + c = 0:\\quad x_1 + x_2 = -\\frac{b}{a} \\qquad x_1 x_2 = \\frac{c}{a}"},{"type":"list","items":["Для приведённого $x^2 + px + q = 0$: $x_1 + x_2 = -p$, $x_1 x_2 = q$.","Работает только если корни существуют: сначала проверь $D \\ge 0$."]}]},{"kicker":"Подбор корней","title":"Решение устно","blocks":[{"type":"text","text":"Ищем два числа с нужной суммой и произведением."},{"type":"list","items":["$x^2 - 7x + 12 = 0$: сумма $7$, произведение $12$ → $3$ и $4$.","$x^2 + 2x - 15 = 0$: сумма $-2$, произведение $-15$ → $3$ и $-5$.","Произведение отрицательно — корни разных знаков."]}]},{"kicker":"Симметричные выражения","title":"Без нахождения корней","blocks":[{"type":"formula","tex":"x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2"},{"type":"formula","tex":"\\frac{1}{x_1} + \\frac{1}{x_2} = \\frac{x_1 + x_2}{x_1 x_2} \\qquad (x_1 - x_2)^2 = (x_1 + x_2)^2 - 4x_1x_2"},{"type":"note","text":"$x^2 - 5x + 3 = 0$: $x_1^2 + x_2^2 = 25 - 6 = 19$."}]},{"kicker":"Обратная задача","title":"Составить уравнение по корням","blocks":[{"type":"formula","tex":"x^2 - (x_1 + x_2)x + x_1x_2 = 0"},{"type":"list","items":["Корни $2$ и $-3$: $x^2 + x - 6 = 0$.","Корни уравнения в два раза больше корней данного: сумма и произведение умножаются на $2$ и $4$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Сумма корней $-\\frac{b}{a}$ — со знаком минус.","Забывают делить на $a$, если $a \\ne 1$.","$x_1^2 + x_2^2 \\ne (x_1 + x_2)^2$.","При $D < 0$ теорема Виета не даёт действительных корней, хотя формулы «работают»."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Теорема","title":"Виет теоремасы","blocks":[{"type":"formula","tex":"ax^2 + bx + c = 0:\\quad x_1 + x_2 = -\\frac{b}{a} \\qquad x_1 x_2 = \\frac{c}{a}"},{"type":"list","items":["Келтірілген $x^2 + px + q = 0$ үшін: $x_1 + x_2 = -p$, $x_1 x_2 = q$.","Тек түбірлер бар болғанда орындалады: алдымен $D \\ge 0$ тексер."]}]},{"kicker":"Түбірлерді таңдау","title":"Ауызша шешу","blocks":[{"type":"text","text":"Қосындысы мен көбейтіндісі керек болатын екі сан іздейміз."},{"type":"list","items":["$x^2 - 7x + 12 = 0$: қосынды $7$, көбейтінді $12$ → $3$ және $4$.","$x^2 + 2x - 15 = 0$: қосынды $-2$, көбейтінді $-15$ → $3$ және $-5$.","Көбейтінді теріс — түбірлердің таңбалары әртүрлі."]}]},{"kicker":"Симметриялы өрнектер","title":"Түбірлерді таппай","blocks":[{"type":"formula","tex":"x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2"},{"type":"formula","tex":"\\frac{1}{x_1} + \\frac{1}{x_2} = \\frac{x_1 + x_2}{x_1 x_2} \\qquad (x_1 - x_2)^2 = (x_1 + x_2)^2 - 4x_1x_2"},{"type":"note","text":"$x^2 - 5x + 3 = 0$: $x_1^2 + x_2^2 = 25 - 6 = 19$."}]},{"kicker":"Кері есеп","title":"Түбірлер бойынша теңдеу құру","blocks":[{"type":"formula","tex":"x^2 - (x_1 + x_2)x + x_1x_2 = 0"},{"type":"list","items":["Түбірлері $2$ және $-3$: $x^2 + x - 6 = 0$.","Түбірлері берілгендерінен екі есе үлкен теңдеу: қосынды $2$-ге, көбейтінді $4$-ке көбейеді."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Түбірлер қосындысы $-\\frac{b}{a}$ — минус таңбасымен.","$a \\ne 1$ болса, $a$-ға бөлуді ұмытады.","$x_1^2 + x_2^2 \\ne (x_1 + x_2)^2$.","$D < 0$ болса, формулалар «есептесе» де, Виет теоремасы нақты түбірлер бермейді."]}]}]}'::jsonb
WHERE slug = 'vieta' AND content_ru IS NULL;

UPDATE public.books
SET content_ru = '{"pages":[{"kicker":"Работа","title":"Механическая работа силы","blocks":[{"type":"formula","tex":"A = Fs\\cos\\alpha"},{"type":"list","items":["$\\alpha$ — угол между силой и перемещением.","$\\alpha < 90°$ — работа положительна, $\\alpha = 90°$ — равна нулю, $\\alpha > 90°$ — отрицательна.","При подъёме на высоту $h$ работа силы тяжести равна $-mgh$. При скольжении по неподвижной поверхности работа трения отрицательна.","Центростремительная сила работы не совершает."]}]},{"kicker":"Работа и график","title":"Переменная сила","blocks":[{"type":"list","items":["Работа = площадь под графиком $F(x)$.","Растяжение пружины: $A = \\frac{kx^2}{2}$ — площадь треугольника.","Работа силы тяжести не зависит от траектории — только от разности высот."]}]},{"kicker":"Мощность","title":"Скорость совершения работы","blocks":[{"type":"formula","tex":"N = \\frac{A}{t} = Fv \\qquad [N] = \\text{Вт}"},{"type":"list","items":["$1$ кВт $= 1000$ Вт.","При постоянной мощности двигателя сила тяги обратна скорости: $F = \\frac{N}{v}$."]}]},{"kicker":"КПД","title":"Коэффициент полезного действия","blocks":[{"type":"formula","tex":"\\eta = \\frac{A_{\\text{пол}}}{A_{\\text{затр}}} \\cdot 100\\%"},{"type":"list","items":["КПД всегда меньше 100%.","Подъём груза по наклонной: полезная работа $mgh$, затраченная $Fl$."]}]},{"kicker":"Ловушки ЕНТ","title":"Где чаще всего ошибаются","blocks":[{"type":"trap","items":["Человек держит груз на месте — работа равна нулю (нет перемещения).","Угол между силой и **перемещением**, а не горизонтом.","Мощность в кВт — переведи в Вт.","КПД больше 100% — признак ошибки в расчёте."]}]}]}'::jsonb,
    content_kk = '{"pages":[{"kicker":"Жұмыс","title":"Күштің механикалық жұмысы","blocks":[{"type":"formula","tex":"A = Fs\\cos\\alpha"},{"type":"list","items":["$\\alpha$ — күш пен орын ауыстыру арасындағы бұрыш.","$\\alpha < 90°$ — жұмыс оң, $\\alpha = 90°$ — нөлге тең, $\\alpha > 90°$ — теріс.","Дене $h$ биіктікке көтерілгенде ауырлық күшінің жұмысы $-mgh$ болады. Қозғалмайтын бетпен сырғанағанда үйкеліс жұмысы теріс.","Центрге тартқыш күш жұмыс жасамайды."]}]},{"kicker":"Жұмыс және график","title":"Айнымалы күш","blocks":[{"type":"list","items":["Жұмыс = $F(x)$ графигінің астындағы аудан.","Серіппені созу: $A = \\frac{kx^2}{2}$ — үшбұрыштың ауданы.","Ауырлық күшінің жұмысы траекторияға тәуелсіз — тек биіктіктер айырымына тәуелді."]}]},{"kicker":"Қуат","title":"Жұмыс жасау жылдамдығы","blocks":[{"type":"formula","tex":"N = \\frac{A}{t} = Fv \\qquad [N] = \\text{Вт}"},{"type":"list","items":["$1$ кВт $= 1000$ Вт.","Қозғалтқыштың қуаты тұрақты болғанда тарту күші жылдамдыққа кері: $F = \\frac{N}{v}$."]}]},{"kicker":"ПӘК","title":"Пайдалы әрекет коэффициенті","blocks":[{"type":"formula","tex":"\\eta = \\frac{A_{\\text{пайд}}}{A_{\\text{жұмс}}} \\cdot 100\\%"},{"type":"list","items":["ПӘК әрқашан 100%-дан кіші.","Жүкті көлбеу бойымен көтеру: пайдалы жұмыс $mgh$, жұмсалған $Fl$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Адам жүкті бір орында ұстап тұр — жұмыс нөлге тең (орын ауыстыру жоқ).","Горизонтпен емес, күш пен **орын ауыстыру** арасындағы бұрыш.","Қуат кВт-пен берілсе — Вт-қа аудар.","100%-дан үлкен ПӘК — есептеудегі қатенің белгісі."]}]}]}'::jsonb
WHERE slug = 'work-power' AND content_ru IS NULL;
